pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit) but penalize fragmentation based on lookahead.
    // If we have a lookahead item, we favor bins that leave enough space to accommodate the next item
    // or bins that result in a near-zero residual (perfect fit).

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating 'dead space': residuals too small to fit any likely item (e.g., < 10)
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If this bin fits the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Balance global state: If we have many open bins, prioritize filling them tightly.
    // If we have few open bins, prioritize preserving capacity.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // Heuristic for new bin: Only open a new bin if the current best fit is very poor.
    // We calibrate the "new bin" cost by comparing it to the mean residual of existing bins.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin to discourage it unless necessary.
        score = 45.0 + (mean_residual * 0.5);
    }

    // Critical constraint: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep space tight.
    // The base score (post_residual) already favors tight fits.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We favor a bin that leaves exactly enough (or slightly more) for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: how much the next item fits perfectly into the remaining space
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalty: if it cannot fit the next item, add a penalty proportional to wasted potential
            score += 20.0;
        }
    }

    // 3. Global Distribution Balancing:
    // If post_residual is significantly lower than the mean_residual of other bins,
    // we are creating a "starving" bin. If it's higher, we are creating a "wasteful" bin.
    // We normalize this by comparing to the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 4. New Bin Thresholding:
    // When deciding whether to open a new bin (where bin_residual == bin_capacity),
    // we only do so if the current open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already tight
        // or if we have very few bins, to avoid fragmenting.
        if mean_residual < 20.0 && open_bins_count > 0 {
            score += 50.0; // Heavily penalize opening a new bin if current ones are efficient
        } else {
            score -= 10.0; // Otherwise, encourage opening a new bin
        }
    }

    // 5. Urgency: If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 significantly.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 0.1);
    }

    // Lookahead influence: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamically adjust strategy based on stream progress.
    // Early in the stream, we are aggressive about packing tightly.
    // Late in the stream, we become more conservative to avoid opening new bins.
    let packing_aggressiveness = 15.0 * (1.0 - progress);
    score += (mean_residual - post) * packing_aggressiveness;

    // Discourage opening a new bin unless the fit is extremely poor in existing bins.
    if bin_residual == bin_capacity {
        // If there are bins that can fit the item, opening a new one is costly.
        if fitting_bins_count > 0 {
            score += 60.0 + (30.0 * progress);
        } else {
            // If no bins fit, the new bin is the only option.
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
