    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty is high, but decreases as we run out of space in existing bins.
        score = 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // If this is the last bin that can fit the item, favor it heavily to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean residual of open bins
        // to encourage uniform bin usage.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle).
    // We penalize high post_residual to keep bins tight.
    let mut score = post;

    // Exponential penalty for creating "dead space" that is too small for common items.
    // As progress increases, we become more conservative about wasting space.
