    score += dead_space_penalty;

    // If this is the only bin that fits, prioritize it heavily (Negative score).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // Heuristic coupling: If a new bin is proposed, penalize it based on how well 
    // the item fits into the current mean residual of existing bins.
    if is_new_bin {
        // If we have many bins open, discourage opening another unless necessary.
        score += (open_bins_count as f64) * 10.0;

        // If the item fits well into the current average, opening a new bin is inefficient.
        score += (100.0 - mean_residual) * 0.5;
    }

    // Lookahead: If the next item is large, prioritize leaving space (lower post_residual).
    // If next_item_size is small, prioritize filling the bin now.
    if next_item_size > 0 {
        let fit_next = (post_residual as i32 - next_item_size as i32) >= 0;
        if fit_next {
            score -= 50.0; // Reward placement that allows the next item to fit.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in (0, 10), it's a "dead zone" for items (min 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly.
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity {
        // High base cost to open a new bin. 
        // Reduce cost if we have many bins open (don't keep too many active) 
        // or if fitting_bins_count is low (we are forced to open one).
        score += 35.0;
        score -= (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // 4. Harmonic Alignment: Favor bins that maintain a residual close to the mean.
    // This keeps bin usage uniform across the set.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    // 5. Progression Weighting: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
