        // We set a threshold: if no existing bin can fit the item with a post_residual < 20, 
        // we might prefer a new bin.
        score = 25.0 - (progress * 5.0);
    } else {
        // Penalty for leaving a "sliver" of space that is hard to fill (e.g., 1-9)
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // Reward filling bins to near-capacity
