    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) that are too small to fit common items
    // We use an exponential penalty for post_residual < 20
    let fragmentation_penalty = if post < 20.0 {
        (20.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size is large, favor bins that can still accommodate it
    // If next_item_size is 0 (end of stream), prioritize closing bins (minimizing residuals)
    let lookahead_bonus = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -15.0 * (1.0 - progress)
        } else {
            10.0 * progress
        }
    } else {
        post * 0.5
    };

    // Discourage opening new bins unless necessary
    // If bin_residual == bin_capacity, this is the "New Bin" candidate
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins could fit the item
            50.0 + (100.0 * (1.0 - progress))
        } else {
            // Necessary to open a new bin
            0.0
        }
    } else {
        0.0
    };

    // Balance residual minimization with the desire to keep bins "open-ended" for later
    // We favor mid-range residuals slightly as the stream progresses to handle late-game packing
    let score = post + fragmentation_penalty + lookahead_bonus + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
