pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space.
    // The smaller the post_residual, the better the fit (Best-Fit logic).
    // We prioritize bins that leave the least space behind.

    // 2. Harmonic Class Logic:
    // If post_residual is small but leaves a gap that is impossible to fill (e.g., < 10),
