    // If the next item is large, we want to reserve space for it.
    // If the current post_residual is smaller than the next_item_size, we penalize it
    // because it forces the next item into a new bin.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost.
    // Only choose a new bin if the best existing bin's score is worse than this threshold.
    if bin_residual == bin_capacity {
