pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20)
    // We prioritize bins where the post_residual is either 0 (perfect fit) 
    // or large enough to accommodate the next item.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic class logic: penalize residuals that are not multiples of common item sizes (20, 25, 50).
    // This helps consolidate remaining space for future packing.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    // If this is the only bin that can fit the item, we are forced to take it.
    // We lower the score significantly to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // If considering a new bin (bin_residual == bin_capacity), apply a penalty 
    // based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);

        // If there are other bins that could have fit this item, make opening a new one very expensive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
