        score += 25.0 + (35.0 * progress);
    } else {
        // Favor bins where the post_residual is close to the next_item_size (Lookahead optimization)
        // We calculate the delta between the post_residual and the next_item_size.
        // If post_residual < next_item_size, it's a poor fit for future items.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                score += (post_residual - next_item_size) as f64 * 0.2;
            }
        }

        // Penalty for creating a "fragment" (very small residual space that is hard to fill)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Encourage balance: penalize bins that deviate significantly from the mean_residual
    // This promotes filling bins somewhat uniformly, keeping options open.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // If this is the last chance to fit an item into an open bin, apply a discount
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We treat post_residual as the primary weight.

    // 2. Harmonic/Modulo Logic: Penalize post_residuals that are small but not zero,
    // as they often create "orphaned" space (e.g., 1-9) that cannot fit subsequent items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
    // significantly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Density Logic: If this is the only bin that can fit the item,
    // force it to have a lower score to prioritize filling it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // 5. New Bin Penalty: If this is a new bin, apply a threshold penalty to 
    // discourage opening new bins unless the fit in existing ones is disastrous.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low, 
        // suggesting existing bins are too tight to accommodate larger items.
        score += 30.0 + (mean_residual * 0.5);
    }

    // 6. Progression Scaling: As we reach the end of the stream, prioritize closing
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

