    // 2. Lookahead matching: If next_item_size fits perfectly into the post_residual,
    // reward this bin heavily to create a "tight pack" pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        // High reward for a perfect fit or near-perfect fit (0-5 gap).
        if gap_after_next == 0 {
