    // 3. Penalty for opening new bins prematurely.
    // If this is a new bin (bin_residual == bin_capacity), only choose it if existing 
    // bins are very poor fits (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin can take the item.
            score += 100.0;
        } else {
            // Reset to neutral if no other choice.
            score = 40.0;
        }
    }

    // 4. Global balance: If the current bin's residual is significantly lower than the 
    // mean_residual of other bins, we are creating a "tight" bin. We prefer to 
    // keep bins balanced in their utilization.
    if (post_residual as f64) < mean_residual {
        score += 5.0; // Slightly penalize making a bin tighter than the current average.
    } else {
        score -= 5.0; // Favor bins that bring the average utilization up.
    }

    // 5. Progression factor: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping many open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Prioritize Best-Fit (minimize post_residual).
    // 2. Penalize opening new bins unless the fit is extremely poor in all existing bins.
    // 3. Incorporate lookahead: If next_item_size fits in post_residual, reward that bin.
    // 4. Use mean_residual to prevent fragmentation.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

