}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the post_residual: we prefer bins that leave little space (Best Fit).
    // Penalize large post_residuals quadratically to avoid "dead space" waste.
    let mut score = post_res * post_res / cap;

    // Interaction 1: Lookahead coupling.
    // If a next item exists, penalize bins that cannot fit it after current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64) * 1.5;
        }
    }

    // Interaction 2: Stream progression.
    // As the stream progresses, prioritize filling existing bins (lower mean_residual) 
    // to avoid fragmentation at the end of the packing process.
    let fill_pressure = (mean_residual / cap) * progress;
    score += fill_pressure * 20.0;

    // Interaction 3: New bin thresholding.
    // If this is a new bin (bin_residual == cap), apply a dynamic cost.
    // We only open a new bin if the cost of placing in existing ones is sufficiently high.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early, but lower penalty towards the end of the stream.
        score += (cap * 0.4) + (progress * 15.0);
    } else {
        // Reward bins that have become "tight" (fitting_bins_count is low).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Interaction 4: Non-linear coupling of open bins count.
    // Discourage excessive bin proliferation using a logarithmic growth penalty.
    score += (open_bins_count as f64).ln() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
