pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice (bin_residual == bin_capacity) 
    // more heavily as we approach the end of the stream to force consolidation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (100.0 - (progress * 50.0)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Calculate "tightness" factor: we prefer post_residuals that are close to 0 
    // (Best Fit), but we penalize very small residuals (e.g., 1-3) that are 
    // likely to become "dead space" if the next item is large.
    let dead_space_penalty = if post > 0.0 && post < 5.0 {
        15.0 / (post + 1.0)
    } else {
        0.0
    };

    // Factor in the lookahead: if the next item doesn't fit in the current post_residual,
    // we slightly prefer bins that leave enough space for it.
    let lookahead_score = if next_item_size > 0 && post < next_item_size as f64 {
        10.0 * (1.0 - progress)
    } else {
