    let base_score = post.powf(1.5) + (mean_residual * 0.5);
    let fitting_penalty = if !is_new_bin && fitting_bins_count > 1 {
        (fitting_bins_count as f64) * 0.5
    } else {
        0.0
    };

    base_score + new_bin_penalty + dead_space_penalty + lookahead_score + fitting_penalty
}

