    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
    }

    // 4. Global State awareness: If we have many open bins, penalize opening a new one 
    // significantly. If open_bins_count is low, be more lenient.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
