            score += 5.0;
        }
    }

    // 4. Mean Residual balancing
    // Avoid creating bins that deviate significantly from the mean efficiency
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling
    // As the stream nears the end, be more aggressive with packing (less picky)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize post_residual values in the range (0, 10), as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic: If we are forced to open a new bin, check if the item is large.
    // If it's a new bin (bin_residual == bin_capacity), increase cost if we have many open bins already.
    if bin_residual == bin_capacity {
