    // Lookahead logic: If a bin fits the next item perfectly, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        // Reward configurations that leave exactly 0 space for the next item.
        if after_next == 0 {
            score -= 30.0;
        }
    }

    // If this is the only bin that fits the current item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure normalization: As the stream progresses, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
