pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle).
    // Lower residual is generally better.
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver": space too small for any likely future item.
    // Given range 10..80, residuals < 10 are highly problematic dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Lookahead logic: if we know the next item, penalize placements that
    // block the next item from fitting into this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward placements that leave exactly enough room for the next item (tight packing).
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // Dynamic threshold for opening a new bin:
    // If the best-fit bin leaves a very poor residual, and we are early in the stream,
    // consider opening a new bin to keep current bins "cleaner".
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open new bin
        } else {
            // Only open a new bin if the mean residual is already quite low, 
            // indicating existing bins are becoming fragmented.
            score += 40.0 + (mean_residual * 0.5);
            if progress > 0.8 {
                score += 100.0; // Aggressively close bins toward end of stream
            }
        }
    } else {
        // Favor bins that are already "half-full" to consolidate space.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

