    let mut score = post_res;

    // Penalty for leaving "dead space" that is unlikely to be filled by future items.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead influence: If the next item fits into the current post_residual, 
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins (Best Fit) and less tolerant of creating new bins.
    if bin_residual == bin_capacity {
