        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // Penalty for bins that deviate significantly from the mean residual of open bins.
        // This promotes consistency in bin utilization.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Final scaling to ensure the "New Bin" penalty is non-linear relative to remaining items.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
