    // If post_residual is < 10 (the minimum item size), it is "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Integration: If the next item is large, prioritize bins that can accommodate it.
    // If next_item_size is large, we want a larger post_residual to avoid opening a new bin soon.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for creating a bin that cannot fit the next item if we have choices.
            score += 40.0;
        } else {
            // Reward bins that leave exactly enough room for the next item.
            score -= (1.0 / (1.0 + (post_residual - next_item_size) as f64)) * 20.0;
        }
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full).
        // If mean_residual is high, we should force usage of existing bins.
        score += mean_residual * 0.5;

        // If only one bin can fit the current item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Progression Scaling:
    // As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. DEAD SPACE AVOIDANCE: Heavily penalize post_residual values that are too small to fit common items 
    // but too large to be considered 'full'. If post_residual is in (0, 10), it is highly likely to become
    // permanent dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. LOOKAHEAD COUPLING: If the next item cannot fit into this post_residual, 
    // penalize this placement to keep the bin open for the next item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0;
    }

    // 3. OPEN BIN PRESSURE: If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it based on how many bins are already open.
    // We only open a new bin if the existing options are very poor.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0) + (progress * 20.0);
    } else {
        // Reward filling existing bins to reduce open_bins_count.
        score -= (1.0 / (open_bins_count as f64 + 1.0)) * 10.0;
    }

    // 4. FRAGMENTATION CONTROL: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. MEAN RESIDUAL STABILIZATION: Avoid bins that deviate significantly from the mean,
    // as they tend to create imbalanced bin states.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: lower post_residual is generally better.
    // However, if we create a "sliver" (too small to fit typical items), penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Lookahead: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further refine: prefer tight fits for the lookahead item.
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Global state awareness:
    // If we have many open bins, be more aggressive at filling them (lower score).
    // If we have very few, be more conservative to avoid stranding items.
    score += (open_bins_count as f64) * 0.2;

    // 4. Mean Residual balancing:
    // Avoid creating bins that are significantly worse than the current average.
    if post_residual as f64 > mean_residual + 15.0 {
        score += 15.0;
    }

    // 5. New Bin logic:
    // Only open a new bin if the current best fit is truly abysmal.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open new bin
        } else {
            // High penalty for opening a new bin if we have fitting options.
            score = 50.0;
        }
    }

    // 6. Progressive tightening:
    // As we approach the end of the stream, prioritize finishing off bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress (late game, be more aggressive)
    if is_new_bin {
        score += (1.0 - progress) * 45.0;
        // If other bins can fit the item, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // Reward bins that are nearing capacity to reduce fragmentation
        // We prefer bins where post_residual is small (tight fit)
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can still accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that keep capacity for the next item
        } else if post_residual < 20 && post_residual > 0 {
            score += 20.0; // Penalize creating "dead zones" that can't fit anything useful
        }
    }

    // Global state awareness: if many bins are open, try to pack tighter
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // Balance against the mean residual of existing bins to keep distribution uniform
    if !is_new_bin {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) which are hard to fill given the input range (10-80).
    // The "Dead Zone" penalty increases as we approach the end of the stream.
    let dead_zone_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post) * (1.0 + 2.0 * progress)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the average, 
    // discouraging fragmentation of space across multiple bins.
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: If the next item is large (e.g., > 50), prioritize keeping 
    // bins with larger residuals open.
    let lookahead_penalty = if next_item_size > 50 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // If this is the only bin that can fit the item, we are forced to take it,
    // but we add a weight to ensure we don't prefer it over a better fit if one exists.
    let necessity_weight = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    // New bin candidate indicator
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As the stream progresses, opening new bins becomes increasingly expensive.
        25.0 + (progress * 20.0)
    } else {
        0.0
    };

    // Combine factors
    // Lower score = higher priority.
    let score = post 
        + dead_zone_penalty 
        + variance_penalty 
        + lookahead_penalty 
        + new_bin_penalty 
        + necessity_weight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

