    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // or leave space for future items.
    let remainder = post_residual % 25;
    score += (remainder as f64) * 0.2;

    // 4. Last Chance Heuristic: If this is the only bin that fits the current item,
    // we must take it unless it is an extremely poor fit.
    if fitting_bins_count == 1 && post_residual > 30 {
        score += 40.0;
    }

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the current best open bin results in a very fragmented space.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual is already high, 
            // suggesting current bins are too fragmented to be useful.
            score = 25.0 + mean_residual;
        }
    }

    // 6. Progression Weighting: As the stream nears the end, become more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
