    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when current ones are available
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Integration: Favor bins that leave room for the next item if possible
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, prioritize it heavily
    // to avoid unnecessary bin creation, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that deviate significantly from the mean
    // This encourages "tightening" existing bins rather than spreading items thin.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 6. Progressive Tightening: As the stream nears completion, become more aggressive
    // about filling existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize leaving a "sliver" (fragmentation).
    // Slivers are typically 1-9 units wide where no standard item fits well.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_margin = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item leaves a clean state or fills the gap
        score -= (100.0 - fit_margin) * 0.8;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current fit is terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high, but scales down if we have many bins 
        // that are already very full (high fragmentation potential).
        score += 45.0 + (mean_residual * 0.5);
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative 
    // with bin space to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
