    // 2. Lookahead optimization: If next_item_size is large, favor keeping space for it.
    // If the current post_residual is smaller than the next item, we effectively block it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Global state: Favor bins that align with the current mean_residual to keep bin states clustered.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    // 4. Scarcity/Efficiency: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic Time Horizon: As we near the end of the stream, prioritize closing bins
    // by rewarding perfect fits (post_residual == 0).
    let progress = step_index as f64 / total_items as f64;
    if post_residual == 0 {
        score -= 10.0 + (progress * 20.0);
    }

    // 6. New Bin Penalty: If this is a new bin (residual == capacity), add a heavy penalty 
    // unless no other open bin can accommodate the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            // If we MUST open a new bin, normalize the penalty based on item size.
            score += item_size as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space remaining (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it is often worse than 0 (perfect fit). 
    // We apply a non-linear penalty for "sliver" residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // heavily reward this bin to favor packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding: as the stream progresses, prioritize closing bins
    // to reduce the total count. If this is the last bin that can fit the item,
    // penalize opening a new bin by adding a significant cost based on progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // If considering a new bin (bin_residual == bin_capacity), apply a cost
    // that scales with the number of open bins and the mean residual.
    // This discourages opening new bins unless the existing ones are very full.
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64) * 2.0;
        let efficiency_penalty = (100.0 - mean_residual) * 0.5;
        score += 40.0 + open_penalty + efficiency_penalty;
    }

    // Non-linear coupling: penalize large residuals more heavily in the 
    // late stages of the stream to force tighter compaction.
    score += (post_res.powi(2) / 100.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
