    // 2. Harmonic Class Logic: Evaluate fit quality based on bin capacity fractions.
    // We favor placements that leave the residual as a multiple of common item sizes (e.g., 20, 25, 33).
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Integration: If the next item is large, prioritize keeping higher residual.
    // If the next item is small, prioritize tight packing.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // If next item won't fit, we want the current post_residual to be as small as possible (Best Fit)
            score -= (post_residual as f64) * 0.2;
        } else {
            // If next item fits, we want to ensure we leave enough space for it
            score -= (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // 4. Pressure management: If this is the only bin that fits, we are forced to take it.
    // Otherwise, we discourage opening new bins unless the fit is excellent.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Only pick if fitting_bins_count is low or if current open bins are very crowded.
        score += 25.0; 
        if open_bins_count > 0 && mean_residual > 40.0 {
            score += 30.0; // Avoid new bins if existing bins have plenty of space
        }
    } else {
        // Existing bin: Apply a bias based on how much space it consumes relative to the mean.
        if (post_residual as f64) < mean_residual {
            score -= 10.0; // Prefer bins that are tighter than average
        }
    }

    // 5. Progression scaling: As the stream nears the end, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
