        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If a future item exists, reward bins that can accommodate it.
    // We favor bins where the post_residual is closer to the next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += 0.5 * diff;
    }

    // Dynamic pressure: As we reach the end of the stream, prioritize closing bins
    // by penalizing the creation of new bins (represented by bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        score += 15.0 + (30.0 * progress);
    }

    // Efficiency bias: Penalize bins that deviate significantly from the current mean residual
    // to encourage uniform packing density across all active bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * residual_deviation;

    // If this is the only bin that fits, strongly reward it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

