        }
    } else {
        // Prefer bins that bring the mean residual closer to a target value (e.g., 15-20)
        // to keep bins packed consistently.
        let deviation = (post_residual as f64 - 15.0).abs();
        score += deviation * 0.5;

        // If this is the last fitting bin, prioritize it to save open bins
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Global state factor: discourage opening too many bins early on
    score += (open_bins_count as f64) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

