    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We heavily penalize post_residuals that are small but non-zero (1..15).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64 / 15.0));
    }

    // Lookahead logic: if next_item_size is large, avoid bins that won't fit it.
    if next_item_size > 0 && post_residual < next_item_size {
