    // Toward the end of the stream (progress -> 1.0), we become highly conservative 
    // about opening new bins to avoid stranding items.
    if is_new_bin {
        // Base cost of opening a new bin is high, but decreases slightly if we have many open bins.
        score += 40.0 * (1.0 + progress) - (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reward it if it's "well-filled" compared to the mean.
        // This encourages filling existing bins rather than spreading items thin.
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // If this is the only bin that fits, prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
