    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (wasted space)
    // We prefer post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy (Harmonic Coupling):
    // If the next item fits into the current post_residual, reward the placement.
    // This acts as a 'Best-Fit-Lookahead' to minimize fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding (The "New Bin" Penalty):
    // If we are considering a new bin (bin_residual == bin_capacity),
    // apply a penalty based on the number of open bins and the mean residual.
    // We only open a new bin if the current open bins are 'too full' to accommodate future items effectively.
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins unnecessarily.
        // Penalty scales with how much space is left in existing bins.
        score += 45.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 1.2);
    } else {
        // 4. Fitting Bin Scarcity:
        // If this is the only bin that fits the current item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Harmonic Penalty for 'difficult' residuals:
        // Residuals that are too small to fit common item sizes (e.g., < 10) are 'dead zones'.
        // Penalize residuals that are small but non-zero.
        if post_residual > 0 && post_residual < 10 {
            score += (10.0 - post_residual as f64) * 5.0;
        }
    }

    // 6. Progressive packing: As we near the end of the stream, prioritize closing bins
    // by being more aggressive with fitting items into existing gaps.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
