    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Matching: If the post_residual is close to the next_item_size, reward it.
    // This creates "perfect" or "near-perfect" pairs.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        // Strongly reward bins where the current placement leaves space for the next item.
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize if we are creating a gap that is too small for the next item
            score += 20.0;
        }
    }

    // 4. Distribution Balancing: Avoid creating bins with residuals significantly lower than the mean.
    // This prevents "starving" bins that might be needed for larger items later.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 15.0;
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression Scaling: Be more conservative towards the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
