    // mean_residual represents the average emptiness; we favor bins closer to the mean.
    let deviation_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += deviation_from_mean * 0.5;

    // Lookahead logic: if the next item is large, avoid leaving a residual smaller than it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 40.0 * (next_item_size as f64 / 100.0);
