        score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Dynamic pressure: As the stream progresses, we become more conservative 
    // about opening new bins. 
    if is_new_bin {
        // Penalize opening a new bin proportional to the number of existing bins
        // and the current progress of the stream.
        score += 40.0 + (progress * 30.0) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward utilizing existing bins. 
        // If fitting_bins_count is 1, this is the last chance for this item;
        // make it very attractive to prevent opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Encourage balancing the load: penalize bins that deviate from the mean residual.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
