    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin candidate logic: If bin_residual == bin_capacity, this is a request to open a new bin.
    // Only return a low score if the average residual is already very low, suggesting 
