pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small "dead" gaps (1-9)
    // which are harder to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global State: If we have many open bins, prioritize filling existing ones 
    // to keep open_bins_count low, especially towards the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 0.5 * progress;

    // 4. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize the new bin based on how many existing bins could have taken the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have other options.
            score += 120.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no other options, this is a neutral/necessary action.
            score = 50.0;
        }
    }

    // 5. Mean Residual Balancing: Encourage keeping bins at similar fullness levels.
    // If this bin's post_residual is significantly lower than the mean, it's a good candidate.
    score += (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;

    // Penalize opening new bins early, but allow it if it leads to a very tight fit
    // New bin candidate is identified by bin_residual == bin_capacity
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller residuals (Best Fit)
    // We add a non-linear penalty for residuals that are too small to fit common items
    // but large enough to waste space (the "fragmentation trap" between 1 and 9)
    let fragmentation_penalty = if r > 0.0 && r < 10.0 { 
        (10.0 - r) * 5.0 
    } else { 
        0.0 
    };

    // Incorporate lookahead: if next_item_size is large, favor bins that leave enough space
    // to accommodate it (Best Fit Decreasing style logic).
    let lookahead_score = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if r < needed {
            r * 2.0 // Penalize bins that will starve the next item
        } else {
            -r * 0.5 // Reward bins that can accommodate the next item
        }
    } else {
        0.0
    };

    // Dynamically adjust strategy based on progress
    // Early game: be conservative, fill existing bins. 
    // Late game: be aggressive to close bins and minimize total count.
    let strategy_bias = if is_new_bin {
        // High penalty for new bins early, lower penalty as we approach the end of stream
        (1.0 - progress) * 150.0 + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Combine terms
    // r^1.5 creates a non-linear preference for tighter fits
    let mut score = r.powf(1.5) + fragmentation_penalty + lookahead_score + strategy_bias;

    // Favor bins that are the only ones capable of fitting the current item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to prevent premature bin opening.
    if bin_residual == bin_capacity {
        // Penalty is higher if many bins are already open or if we are early in the stream.
        // We only want to open a new bin if the current fit quality is extremely poor.
        score += 45.0 + (open_bins_count as f64 * 2.0) + (step_index as f64 / total_items as f64 * 10.0);
    } else {
        // 2. Harmonic alignment: Favor filling bins to leave "clean" residuals for common item sizes.
        // Penalty for leaving small, unusable slivers (e.g., 1-9 range).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 - (post_residual as f64 * 0.5);
        }

        // 3. Lookahead synergy: If the next item fits into the post_residual, reduce the score.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
            // Additional reward for "perfect" fits (exact matches).
            if next_item_size == post_residual {
                score -= 20.0;
            }
        }

        // 4. Distribution balancing: If current bin residual is far from the mean, penalize.
        // This encourages leveling the load across bins.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it falls in the "unusable" range (1..10).
    // Small gaps are the primary cause of bin inefficiency.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling existing bins to consolidate space.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, prioritize it highly
    // to avoid unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Adjustment: As the stream nears the end, prioritize tightly packing
    // remaining items to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that likely won't fit future items)
    // If post_residual is small (e.g., < 10), it's often a waste unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead matching
    // If next_item_size fits perfectly into the remaining space, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave space for the next item, but penalize excessive fragmentation
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 3. Global state awareness (Mean Residual)
    // If this bin's post_residual is significantly worse than the current average, penalize it.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 20.0;
    }

    // 4. Decision logic for New Bin vs Existing
    // If this is a new bin (bin_residual == bin_capacity):
    // Only choose a new bin if we are forced to (no other good options) or if the current bins are all "cluttered".
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can fit the item
            score += 45.0;
        }
    } else {
        // If it's an existing bin, favor it if it's the last chance (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Progression scaling
    // Towards the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize the residual space.
    // If we create a very small residual, we are likely creating wasted space (fragmentation).
    // Penalize post_residual values that are too small to fit common items (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 2. Lookahead Awareness:
    // If the next item cannot fit into the current post_residual, we penalize this placement.
    // This encourages saving space for the next item in the sequence.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // 3. Dynamic New Bin Threshold:
    // When residual is full capacity, we are evaluating a new bin.
    // We only open a new bin if the current mean_residual across open bins is poor,
    // or if we are nearing the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 45.0 + (progress * 10.0);

        // If we have many open bins with high residuals, don't open a new one.
        if mean_residual > 20.0 {
            score += 20.0;
        }
    }

    // 4. Fitting Constraint:
    // If this is the only bin that can fit the item, we lower the score to prioritize it
    // over opening a new bin (if the new bin logic above is competitive).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 5. Global State Influence:
    // Prefer bins that keep the global mean residual closer to the ideal (approx 15-20).
    let deviation = (mean_residual - 18.0).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (1-9 range is often "dead space")
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        20.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that align with the next item to minimize future fragmentation
    let lookahead_benefit = if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for perfect or near-perfect fit for the next item
            let diff = (post_residual - next_item_size) as f64;
            -15.0 * (1.0 / (1.0 + diff))
        } else {
            // Penalize if we block the next item from fitting here
            10.0
        }
    } else {
        0.0
    };

    // Dynamic pressure: as the stream progresses, prioritize tighter packing
    // and discourage opening new bins unless the fit is truly terrible
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // Base penalty for new bin is high, but decreases slightly as we reach the end
        // to ensure we don't leave bins half-empty at the finish
        (40.0 + (progress * 20.0)) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Favor bins that bring the mean residual closer to a target "sweet spot" (e.g., 15)
    // to keep bins balanced rather than having one very full and many very empty.
    let balance_score = (post_res - 15.0).abs() * 0.2;

    // Combine heuristics: 
    // Lower score is better.
    let score = post_res 
        + fragmentation_penalty 
        + lookahead_benefit 
        + new_bin_penalty 
        + balance_score;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common small-to-medium items,
    // but not small enough to be considered "perfectly packed". 
    // We treat residuals in the range [1, 9] as "dead space" traps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fragmentation Control: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily (Best-Fit principle).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Density Balancing: If the bin is new (bin_residual == bin_capacity), 
    // penalize it based on how many bins are already open to discourage spreading items too thin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If the item is large, opening a new bin is better than putting it in a crowded bin.
        if item_size > 60 {
            score -= 20.0;
        }
    }

    // 5. Residual Alignment: Favor bins where the post_residual is closer to the mean_residual
    // of other bins, promoting a uniform distribution of remaining space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Progress-based refinement: As the stream nears completion, become more aggressive 
    // about packing into existing bins to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
