pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // Base score is already post_residual.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We favor placements that leave exactly enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + diff); 
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the fit is excellent.
    // If bin_residual == capacity, we are evaluating a brand-new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current item is very large or if we have many open bins
        // already that are mostly full (mean_residual is low).
        if item_size > 70 {
            score -= 10.0;
        } else if mean_residual < 20.0 && open_bins_count > 2 {
            score += 40.0; // Heavily penalize opening new bins if existing ones are tight
        } else {
            score += 25.0; // Baseline penalty for new bin creation
        }
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Density Balancing: If we are late in the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Prioritize Best-Fit (smaller post_residual is better).
    // 2. Penalize opening new bins unless the current bin state is "constrained" (high mean_residual).
    // 3. Use lookahead (next_item_size) to avoid creating "orphaned" space that cannot fit future items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for opening a new bin
    if is_new_bin {
        // Only open new if we have many open bins already or if fitting_bins_count is 0
        // We scale the cost of a new bin by the progress of the stream to force tighter packing later
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward fits that leave exactly enough space for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect fit for lookahead is highly rewarded
                score -= (bin_capacity - post_residual) as f64 * 0.2;
            } else {
                // If it doesn't fit the next item, penalize proportionally
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }

        // Penalty for creating a "fragmented" bin (too small for most items)
        if post_residual < 10 {
            score += 15.0;
        }

        // If this is the last fitting bin, prioritize using it to keep open_bins_count low
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Dynamic adjustment based on mean_residual to prevent massive divergence
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle).
    // We want to minimize post_residual, so lower is better.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, the penalty for opening a new bin should increase 
    // to encourage filling existing capacity.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    }

    // Lookahead logic: if the next item is large, favor bins that leave 
    // enough space for it (or leave the bin as empty as possible if it can't fit).
    if next_item_size > 0 {
        let fit_next = post_residual >= next_item_size;
        if !fit_next {
            // Penalize bins that are "almost" large enough for the next item but fail,
            // as they create dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward bins that can accommodate the next item.
            score -= 10.0;
        }
    }

    // Coupling with the mean residual of the system:
    // If our current post_residual is significantly worse than the system average, 
    // penalize it to force tighter packing.
    let residual_diff = post_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.2;
    }

    // If this is the only bin that can fit the item, give it a strong preference 
    // (negative score) to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Non-linear scaling based on open bins count to prevent fragmentation
    // at the end of the stream.
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    score
}

