    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit common items
    // If post_residual is in the range [1, 9], it's essentially "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit Bias: Encourage filling bins tightly (minimize post_residual)
    // We already have post_residual in the base score, but we add a quadratic term for tight fits.
    score += (post_residual as f64).powi(2) * 0.05;

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global Consolidation Pressure: If we have many open bins, penalize opening new ones.
    // If this is a new bin (bin_residual == bin_capacity), increase its score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 5. Mean residual alignment: Avoid creating bins that deviate significantly from the current average
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Scarcity avoidance: If this is the only bin that fits the item (fitting_bins_count == 1),
    // reduce the score to ensure we use existing capacity before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // However, if post_residual is very small (e.g., < 10), it creates "dead space" 
    // that is hard to fill later. 
    if post_residual < 10 {
        score += 20.0 - (post_residual as f64 * 2.0);
    }

    // 2. Lookahead Matching: If the next item fits perfectly into the post_residual,
    // we heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        // Reward small remaining gaps after placing the next item.
        score -= (100.0 - fit_gap * 1.5);
    }

    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from 
    // the current population's mean_residual to prevent fragmentation.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. New Bin Thresholding: Penalize opening a new bin unless existing options 
    // are truly terrible (all result in high post_residual or poor lookahead).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins already or if the item is large.
        // If fitting_bins_count is high, we should almost never open a new bin.
        score += (fitting_bins_count as f64 * 50.0);

        // If the item is very large, it's better to start a new bin than to 
        // fragment a nearly full one.
        if item_size > 70 {
            score -= 40.0;
        }
    }

    // 5. Progress weighting: In the final stages, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals (Best Fit)
    // We want post_residual to be as small as possible (close to 0).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: 
    // If the next item can fit in the current post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.8;
    }

    // 3. Prevent fragmentation:
    // If we are late in the stream, penalize opening new bins unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing bin could fit the item
            score += 150.0 * (1.0 - progress);
        }
    } else {
        // 4. Global balance:
        // Penalize bins that deviate significantly from the mean residual of open bins
        // to encourage packing density uniformity.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Last-chance logic:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Tightness reward:
    // Reward packing that leaves very little space (near 0), which is usually ideal.
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
