    // We favor smaller post_residuals (tight packing).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: 
    // Reward bins that leave a residual which is a multiple of common item sizes (e.g., 20, 25, 33).
    // This reduces fragmentation by aligning future items with bin boundaries.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.8;

    // 3. Lookahead Synergy:
    // If next_item_size fits in the current post_residual, drastically lower the score.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
    }

    // 4. New Bin Threshold:
    // If the bin is new (bin_residual == bin_capacity), apply a heavy penalty to 
    // force the algorithm to prefer filling existing bins unless they are truly poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If we have many open bins, penalize opening another one even more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Urgency/Saturation:
    // If this is the last fitting bin for the current item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current mean residual.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
