        }
    }

    // 3. New Bin Management: Discourage opening new bins unless necessary.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we are forced to, or if the mean residual of current bins is very low
        // (meaning current bins are nearly full and inefficient for future items).
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 20.0;
        }
    }

    // 4. Global Density Awareness: If we are late in the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 30.0;
    }

    // 5. Mean Deviation: Discourage bins that deviate significantly from the current mean residual
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: Favor bins that result in the smallest post_residual.
    // This is already the base score.

    // 2. Lookahead optimization: If a future item fits perfectly or near-perfectly into the current 
    // post_residual, reduce the score to prioritize this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= (100.0 - gap) * 0.15;
    }

    // 3. Penalty for fragmentation: If the post_residual is small but not zero (a "sliver"),
    // it is often useless. Penalize slivers (e.g., 1-9) unless they are exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If we have few open bins, be more selective about opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin unless the mean residual of existing bins is already very low.
        score += 15.0 + (mean_residual * 0.5);

        // As we approach the end of the stream, penalize opening new bins more heavily
        // to encourage packing into existing ones.
        score += progress * 20.0;
    } else {
        // Reward filling bins that are already below the mean residual to consolidate space.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 5. Critical check: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

