        // flexibility when the bin density is already high.
        score += 50.0 * (1.0 - progress * 0.5);

        // If we have many open bins that can fit this, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 100.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // For existing bins, reward configurations that leave space for lookahead (next_item_size)
        // If next_item_size fits in post_residual, we reward this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }

        // Avoid "fragmentation": penalize residuals that are too small to fit common items 
        // (assuming average item size is related to the bin_capacity/3)
        if post_residual > 0 && post_residual < 20 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Interaction with mean_residual: If current bin is worse than the mean, penalize it.
    // This pushes items into bins that are already "tighter" than the average.
    if !is_new_bin {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

