    // 4. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If the bin being evaluated is a new bin (bin_residual == bin_capacity),
    // apply a penalty proportional to the number of open bins to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;

        // If there are other bins that could fit this item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate too far from the average
    // to keep bins packed evenly across the set.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (fragmentation):
    // If we leave a small gap that is unlikely to fit most items (e.g., < 15), penalize it.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // 2. Lookahead optimization:
    // If the post_residual can perfectly or near-perfectly accommodate the next item, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough room for the next item (synergy).
            let diff = (post_residual - next_item_size) as f64;
            score -= (50.0 - diff).max(0.0);
        } else {
            // Penalize bins that would make the next item require a new bin.
            score += 20.0;
        }
    }

    // 3. Global Bin Management:
    // If this is a new bin (residual == capacity), penalize it relative to the fitting_bins_count.
    // If other bins can fit the item, we should strongly prefer them over opening a new one.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 60.0;

        // As the stream progresses, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

