    // We want to minimize this (Best Fit strategy).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10 (the minimum item size), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly (Best Fit on lookahead)
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize bins that would prevent the next item from fitting if it could have fit otherwise
            score += 15.0;
        }
    }

    // Global state awareness: 
    // If we are late in the stream, prioritize closing bins (lower mean_residual)
    if progress > 0.8 {
        score += mean_residual * 0.5;
    }

    // New Bin Logic:
    // Only open a new bin (bin_residual == bin_capacity) if the best existing fit is poor.
    // If fitting_bins_count is high, we have many options; avoid opening new bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fitting options
            score += 80.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no bins fit, we must open a new one; keep score neutral
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
