    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are too small to fit 
    // the next item are often worse than leaving a larger residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic adaptation: as the stream progresses, tighten the packing constraints.
    // Near the end of the stream, we become more aggressive about filling bins 
    // to avoid leaving scattered items.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // Favor bins that align with the global mean residual to keep bin states uniform.
    // This reduces the variance of open bins, preventing "fragmentation".
    let mean_diff = (post_res - mean_residual).abs();
    score += mean_diff * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
