    // If post_residual is a multiple of 20, it's more likely to accommodate future items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 5. Avoid premature new bin opening: If we are not forced to open a new bin, 
    // apply a heavy penalty to the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    // 6. Dynamic pressure: as the stream progresses, favor tighter packing to prevent 
    // bin fragmentation towards the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Balance load: if this bin is significantly emptier than the average, 
    // it might be better to fill it rather than creating a new one.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "post_residual" (Best Fit), but penalize gaps that are too small to be useful
    // for future items (10-20 range), while balancing the total number of bins currently in play.

    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize post_residuals that fall into the "unusable" range (1-9).
    // These are often worse than leaving a larger gap or opening a new bin.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Integration: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // if we have many bins already open, unless the fit is perfect (post_residual == 0).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 5.0;
        }
    }

    // 4. Tight Fit Reward: If this is the only bin that can fit the item, 
    // don't penalize it too harshly, but favor bins that leave more room for future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Global Mean Normalization: Discourage bins that are significantly 
    // more empty than the current average to maintain bin density.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating bins that are too empty
    // If we open a new bin, bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        score += 45.0; // Resistance to opening new bins
    }

    // 2. Lookahead logic: if we can fit the next item perfectly (Best Fit)
    if next_item_size > 0 {
        let gap = post_residual as i32 - next_item_size as i32;
        if gap >= 0 {
            // Reward bins that leave space exactly matching the next item
            score -= (50.0 / (gap as f64 + 1.0));
        } else {
            // Penalize if the next item won't fit in this bin
            score += 5.0;
        }
    }

    // 3. Density maintenance: avoid creating bins that deviate significantly from mean_residual
    // We prefer bins that bring the current state closer to the historical average
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Critical thresholding: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression adjustment: As the stream nears the end, become more aggressive 
    // in packing tightly to finish with fewer bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (1-5 units)
    if post_residual > 0 && post_residual <= 5 {
        score += 45.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin, penalize based on current global state.
    if bin_residual == bin_capacity {
        // Only open new bins if we have too many open bins already or if the item is large.
        // As progress increases, become more conservative about opening new bins.
        score += (open_bins_count as f64) * 2.0;
        score += (1.0 - progress) * 20.0;

        if item_size < 40 {
