        }
    } else {
        // 4. Global State Awareness: If this bin is the only one that fits the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the mean.
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

