    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill).
    // If post_residual is < 10, it's likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
