    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Dynamic scaling based on stream progression: 
    // Early on, we are aggressive about packing (minimize residuals).
    // Near the end, we become conservative to avoid opening new bins.
    score += (open_bins_count as f64 * 5.0) * progress;

    // Penalize new bin creation (bin_residual == bin_capacity) 
    // unless the current open bins are very full (high mean_residual penalty).
    if bin_residual == bin_capacity {
        score += 35.0 - (mean_residual * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

