    // 4. Global State Awareness: If we are late in the stream, favor utilizing 
    // existing bins (lower mean_residual) to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.5;

    // 5. Modulo-based Harmonic alignment: Favor bins that maintain a residual 
    // that is a multiple of the current item size, minimizing "remainder" entropy.
    if item_size > 0 && post_residual % item_size == 0 {
