        score += 2500.0 * (1.0 - progress).powf(0.5);
    }

    // Lookahead coupling: if the next item is large, penalize small post_residuals
    // that might trap the bin into a state where the next large item cannot fit.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post_res < next_item {
            score += 400.0 * (1.0 - post_res / next_item);
        }
    }

    // Reward bins that bring the mean residual closer to a "sweet spot" (e.g., 20-30)
    // to keep options open for future items.
    let target_mean = 25.0;
    let new_mean = (mean_residual * open_bins_count as f64 - bin_residual as f64 + post_res) / open_bins_count as f64;
    score += 100.0 * (new_mean - target_mean).abs();

    // If only one bin can fit the current item, prioritize using it to prevent
    // unnecessary bin fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1000.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" that cannot accommodate common item sizes (10-30)
    // We prioritize bins where the post_residual is a multiple of larger potential items
    let fragment_penalty = if post_residual < 10 {
        200.0 // Hard penalty for near-empty slivers
    } else if post_residual < 20 {
        50.0 
    } else {
        0.0
    };
    score += fragment_penalty;

    // Lookahead logic: if next_item_size is large, favor larger residuals (smaller post_residual is bad)
    if next_item_size > 0 {
