    // but large enough to waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If a next item exists, favor bins that leave space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly (Best Fit for lookahead)
            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.5;
        } else {
            // Penalize bins that block the next item from fitting
            score += 15.0;
        }
    }

    // Dynamic thresholding: If we are late in the stream, be more conservative with opening new bins
    if is_new_bin {
        if open_bins_count > 0 {
            // Discourage opening a new bin if existing bins are available
            score += 40.0 + (progress * 30.0);
        }
        // Penalize opening a new bin if the item could have fit in an existing bin
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage using bins that are already 'well-filled' (close to mean_residual)
        // This helps cluster items and keep open_bins_count low
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Special handling for "last chance" bins
    if fitting_bins_count == 1 && !is_new_bin {
        // If this is the only bin that fits, prioritize it heavily
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values that are small but > 0, especially as the stream progresses.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if next_item_size is known, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on progress.
    // We want to avoid opening new bins late in the game unless necessary.
    if bin_residual == bin_capacity {
        score += 30.0 + (progress * 40.0);
    }

    // Bias towards bins that are already closer to being full to consolidate space.
    // We subtract a factor proportional to how much the bin is already filled.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Favor bins that have a residual close to the mean residual of all open bins.
    // This helps keep bins balanced in terms of remaining capacity.
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prefer smaller post_residuals to maximize bin density.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class logic: Identify "tightness" of the fit.
    // If post_residual is small (e.g., < 10), it's a high-quality fit.
    if post_residual < 10 {
        score -= 50.0;
    }

    // 3. Lookahead Integration: If next_item_size is large, avoid leaving a residual
    // that is just slightly too small to fit that next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalty for "blocking" the next item
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else if post_residual >= next_item_size {
            // Reward for "enabling" the next item
            score -= (next_item_size as f64) * 0.8;
        }
    }

    // 4. Thresholding/New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if
    // the existing bins are "crowded" or if it is the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // Must open new bin
        } else {
            // Penalize opening a new bin unless existing bins are very full
            score += (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Progression scaling: As we approach the end of the stream,
    // be more aggressive about filling bins to reduce the final count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
