    // Residuals near 0 or 100 are often better than residuals near 50.
    let residual_mod = post_residual % 20;
    score += (residual_mod as f64) * 0.5;

    // 6. Progress Scaling: As the stream progresses, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize gaps that are too small to fit any expected item (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current options are poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If we have many fitting bins, opening a new one is almost always suboptimal.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tightness bias: Prefer filling bins to be as full as possible (minimizing post_residual).
    // We adjust the score to favor bins that reach a near-full state.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better than the mean,
    // favor it to keep the "good" bins active and consistent.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that leave the smallest leftover space.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, 
    // we reward this bin heavily to create a "perfect pair" effect.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_delta = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_delta) * 1.5;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current 
    // fitting options are extremely poor (i.e., they create large dead space).
    if bin_residual == bin_capacity {
        // If we are forced to open a new bin, only do it if the mean_residual 
        // of existing bins is already quite small (meaning we've exhausted good fits).
        score += mean_residual * 2.0;

        // If there are other bins that could fit the item, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 150.0;
        }
    }

    // 4. Fragmentation Avoidance: If the post_residual is small but > 0, 
    // it's often unusable. Penalize "slivers" that are too small for most items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Progression Weighting: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to avoid straggler bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin with very small, unusable remaining space (1..9)
    // This forces the algorithm to prefer bins that leave larger, more versatile gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead logic: if the next item is large, favor keeping larger residuals (lower score)
    // If the next item is small, we are less sensitive to tight fits.
    if next_item_size > 0 {
        let fit_next = (post_residual as i32 - next_item_size as i32) as f64;
        if fit_next < 0.0 {
            score += 15.0;
        } else {
            score -= 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Global state weighting: penalize opening new bins as we approach the end of the stream
    // to force consolidation, but allow it early if the fit is perfect.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Reward bins that keep the mean residual closer to the item_size, 
    // encouraging balanced bin utilization.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // Favor bins that are already "tight" if the current item fits well,
    // reducing the number of active open bins.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the residual space after placement
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: higher early in the stream, lower as we approach the end (to prevent fragmentation)
    if is_new_bin {
        score += 15.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward tight fits (Best-Fit principle)
        // We penalize larger post_residuals exponentially to favor bins that reach capacity
        score += (post_residual as f64).powf(1.2);

        // If next_item_size is known, penalize placements that leave too little room for it
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 2.0;
            }
        }

        // Penalty if this is the last fitting bin: 
        // If we have other options, we prefer not to use the one that is currently "tightest" 
        // if it could accommodate a future item better, but here we prioritize filling this bin.
        if fitting_bins_count == 1 {
            score -= 5.0; 
        }
    }

    // Interaction term: If the current bin's residual is significantly above the mean, 
    // it's a "loose" bin; penalize it to force consolidation.
    let residual_deviation = (bin_residual as f64 - mean_residual).max(0.0);
    score += residual_deviation * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We prioritize bins where the remaining space is small, but not zero (dead space avoidance).
    if post_residual == 0 {
        score -= 5.0; // Reward perfect fits
    } else if post_residual < 10 {
        score += 20.0; // Penalize "sliver" gaps that are hard to fill later
    }

    // 2. Harmonic Lookahead Coupling
    // If the next item can fit into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Adaptive Thresholding based on mean_residual
    // If our current bin is significantly better than the average, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. New Bin Logic
    // If this is a new bin (bin_residual == bin_capacity), only pick it if we have no good choices.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can accommodate
            score += 150.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If we must open a new bin, normalize the score
            score = 50.0;
        }
    }

    // 5. Progression Scaling
    // As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it is likely to be wasted.
    // We penalize this heavily to force tighter packing.
    if post_residual > 0 && post_residual < 10 {
