    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if we have many bins already open.
    // If this is a new bin (bin_residual == bin_capacity), increase score relative to open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Fitting Count Utility: If this is the ONLY bin that fits the item (fitting_bins_count == 1),
    // give it a slight preference to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // 5. Global Efficiency Adjustment: If the current bin's residual is significantly lower than the
    // mean_residual, it is a "tight" bin. We prefer packing into tighter bins to keep others open.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the base post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for any future items (below 10)
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // Lookahead: Reward placements that create a post_residual matching the next_item_size
    // This effectively implements a 'Perfect Fit' lookahead heuristic
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // Global state optimization:
    // If we have very few open bins, prioritize packing tightly to save overall capacity.
    // If we have many bins, prioritize keeping the mean_residual high to avoid fragmentation.
    let density_factor = (open_bins_count as f64) / (1.0 + (step_index as f64 / total_items as f64) * 10.0);
    score += (post_residual as f64 - mean_residual) * 0.2 * density_factor;

    // Critical constraint: If this is the only bin that fits, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Discourage opening a new bin (where bin_residual == bin_capacity)
    // unless the fit in all existing bins is objectively terrible (high post_residual)
    if bin_residual == bin_capacity {
        // New bin penalty: Only open if existing options are highly inefficient
        score += 35.0;
        // As the stream progresses, make it slightly harder to open new bins
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

