    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if the fit is terrible
        // Penalize new bins based on how many bins are already open and the progress
        score += 45.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    } else {
        // If we are in an existing bin, evaluate the impact of the next item
        if next_item_size > 0 {
