    }

    // Critical threshold: if this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement; we want to minimize this (Best Fit)
    // but we adjust based on the potential to fit future items.
    let mut score = post_res;

    // Penalty for leaving a very small gap that is statistically unlikely to be filled (e.g., < 10).
    // The threshold is dynamic based on the mean_residual of current bins.
    if post_res > 0.0 && post_res < (mean_residual * 0.5) {
