    // in a bin where the next item will no longer fit if it otherwise could have.
    if next_item_size > 0 {
        if post_res >= next_item_size as f64 && post_res < (next_item_size as f64 + 10.0) {
            // Reward bins that are "perfect" for the next item
            score -= 25.0 * (1.0 - progress);
