    // New Bin Logic: Discourage opening a new bin unless the current fit is extremely poor.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high, scaled by current open bin count and progress.
        score = 25.0 + (open_bins_count as f64 * 2.0) + (progress * 15.0);
    } else {
        // If the bin is already open, apply a slight pressure to consolidate items
        // by favoring bins that are already more filled (lower post_residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
