    // We want to minimize the gap left behind.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // Identify if the post_residual is "harmonic" relative to common item sizes.
    // If the remaining space is small, it's likely "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Heavy penalty for creating slivers of unusable space
    }

    // 3. Lookahead Integration:
    // If a future item fits perfectly into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.8; 
    }

    // 4. Fitting Bin Scarcity:
    // If this is the only bin that can fit the item, we are forced to take it.
    // However, if we have many choices, we should be more selective.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64) * 2.0;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize opening a new bin unless the existing bins have very poor residuals.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0; // Required to start
        } else {
            // Only open a new bin if the mean residual of existing bins is already tight (< 20)
            // or if the item is large.
            score += 40.0 + (mean_residual * 0.5);
            if item_size > 70 {
                score -= 30.0;
            }
        }
    }

    // 6. Progressive Pressure:
    // As we approach the end of the stream, tighten the requirements.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
