            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                score -= 15.0;
            }
        }
    }

    // 3. Pressure management: If this is the last fitting bin, discourage opening a new one 
    // unless the current fit is extremely inefficient.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Global balance: Penalize opening new bins if the average residual is already high
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if mean_residual > 30.0 {
            score += 50.0;
        } else {
            score += 10.0;
        }
    }

    // 5. Dynamic scaling: Favor filling bins to capacity as the stream approaches its end
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Decreasing logic: lower post_residual is generally better.
    // We penalize new bins heavily early on, but allow them if the fit is perfect.
    if is_new_bin {
        score = 45.0 + (progress * 20.0);
        if post_residual == 0 { score -= 30.0; } // Perfect fill bonus
    } else {
        // 2. Lookahead: penalize if the next item is large and won't fit in the current post_residual
        if next_item_size > 0 && next_item_size > post_residual {
            score += 15.0 * (next_item_size as f64 / 100.0);
        }

        // 3. Global state: if mean residual is high, we are being too loose; tighten up.
        // Encourage using bins that keep the mean residual balanced.
        score += (mean_residual - post_residual as f64) * 0.5;

        // 4. Scarcity: If this is the only bin that fits the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // 5. Fragmentation avoidance: Penalize leaving small gaps that are hard to fill (1-9 range)
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }

        // 6. Prefer filling bins that are already partially full (lower post_residual)
        // weighted by the current bin_residual relative to capacity.
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (1-9 range)
    // because items are >= 10.
    let stranded_penalty = if post < 10.0 && post > 0.0 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Factor in the lookahead: if the next item is large, we want to prioritize 
    // keeping large residuals, or if it fits, we want to leave space.
    let lookahead_impact = if next_item_size > 0 {
        let fit_next = (post >= next_item_size as f64) as i32 as f64;
        (1.0 - fit_next) * 15.0
    } else {
        0.0
    };

    // Dynamic preference for Best Fit vs First Fit based on progress
    // Early stage: be aggressive (low score for tight fits).
    // Late stage: be conservative (penalize opening new bins).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Non-linear coupling: prefer post_residual values that are either 0 
    // (perfect fit) or large enough to accommodate the mean of future items.
    // We use a quadratic term to punish middle-of-the-road gaps.
    let gap_efficiency = (post * 0.1).powf(1.5);

    let score = post + stranded_penalty + lookahead_impact + new_bin_penalty + gap_efficiency;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

