    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when existing ones are available.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on current usage.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 3. Lookahead Synergy: If a next item exists, reward bins that leave space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for creating a perfect fit for the next item
        } else if post_residual > 0 {
            score += 15.0; // Penalty for stranding the next item
        }
    }

    // 4. Fitting Density: If this is the last bin that can fit the item, 
    // prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the mean to maintain uniform fill.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
