    // If we have many fitting bins, prefer the one that leaves the least space.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: 
    // Penalize post_residuals that are "unproductive" (too small to fit common items).
    // If post_residual is between 1 and 9, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead Synergy:
    // If we have a next item, favor bins where the remaining space is enough to fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Penalize creating a bin that cannot fit the next item if it's a large item.
            if next_item_size > 50 {
                score += 15.0;
            }
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy base cost
    // to force the algorithm to use existing bins unless they are all poor fits.
    if bin_residual == bin_capacity {
        score = 60.0; 
        // If there are many open bins, opening a new one is very expensive.
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Mean Residual Balancing:
    // If the current bin's post_residual is significantly worse than the average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 10.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

