    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We define "dead" as < 10 (since min item size is 1).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 40.0;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, become more aggressive in packing tightly (penalize opening new bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is expensive, but the cost increases as we reach the end of the stream
        // to force the algorithm to utilize existing bins more effectively.
        score += 15.0 + (30.0 * progress);

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward bins that have residuals closer to the mean, promoting balanced filling.
        let deviation = (post - mean_residual).abs();
        score += 0.5 * deviation;
    }

