    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic class logic: favor bins that leave residuals which are multiples of 
    // common item ranges, or that align with the mean density of the system.
    let residual_mod = (post_residual % 25) as f64;
    score += residual_mod * 0.5;

    // Density normalization: penalize opening new bins unless the mean_residual is high.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold.
    if bin_residual == bin_capacity {
