    // Fitting threshold: if this is the only bin that can fit the item, 
    // force selection to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Progression weight: as we near the end of the stream, prioritize closing bins
    // by packing them tighter (penalize large post_residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps 
    // that are too small to fit common future items.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it is likely unusable 
    // given the item distribution (10..100). Penalize these "sliver" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Coupling: If the next item is large, prioritize bins that can 
    // accommodate it after this placement.
    if next_item_size > 0 {
