    // based on how many other bins are already open and their average utilization.
    if is_new_bin {
        // Penalty for opening a new bin is scaled by the current bin count 
        // and the mean residual of existing bins.
        score += (open_bins_count as f64 * 2.0) + (100.0 - mean_residual);
    } else {
        // For existing bins, favor those that bring the bin closer to full (Best Fit).
        // We subtract the post_residual indirectly by penalizing larger residuals.
        score += (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 4. Scarcity Constraint: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin openings.
    if fitting_bins_count == 1 && !is_new_bin {
