    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small fragments that cannot fit upcoming items.
    // We prioritize bins that leave exactly enough room for the next_item_size if possible.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If the residual is too small for the next item, we penalize it unless it is exactly 0.
    if post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Reward perfect fits: If post_residual is exactly 0, it is a high-priority placement.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 3. Lookahead Matching: If the post_residual is close to the next_item_size, reward it.
    // This promotes "perfect" pairs in the bin.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += diff * 0.5;
    }

    // 4. Global balance: If this is the last chance for the current item (fitting_bins_count == 1),
    // we should be more lenient with the residual to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Constraint: When considering a new bin (bin_residual == bin_capacity),
    // we only pick it if the penalty for fitting into existing bins is extremely high.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing bins are quite full (low mean_residual).
        // If mean_residual is large, we should have used an existing one.
        score += (mean_residual * 2.0) + (open_bins_count as f64 * 0.5);
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
