    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Coupling: If next_item_size is known, reward leaving space
    // that fits the next item perfectly, or penalize blocking a future fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item.
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalty for creating a bin that is too small for the next item.
            score += 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // heavily prioritize it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Mean Residual Alignment: Penalize bins that deviate 
    // significantly from the average residual to promote uniform fill.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
