    // Penalty for creating 'dead space' (small residuals < 10) that are hard to fill later.
    // We scale this penalty by progress to be more aggressive as the stream nears completion.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress);
    }

    // Reward bins that can accommodate the lookahead item (next_item_size).
    // If the current post_residual can hold the next item, we lower the score.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.5;
    }

    // If this is a new bin, apply a structural penalty that decays over time.
    // We want to force usage of existing bins early, but allow new bins if open bins are too full.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);

        // Penalize opening a new bin if other bins still have room for the current item.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Coupling: If the current bin is significantly "emptier" than the mean, 
    // it's a "fresher" bin. We penalize it slightly to encourage packing into 
    // tighter bins first, balancing the load.
    let bin_fullness = (bin_capacity - bin_residual) as f64;
    if bin_fullness < mean_residual {
        score += (mean_residual - bin_fullness) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals < 10 are often unusable for the given range 10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic/Modulo pressure: Reward residuals that are multiples of 20, 
    // as they increase the likelihood of accommodating larger items later.
    if post_residual % 20 == 0 {
