    // 4. Thresholding: If this is the only fitting bin, heavily prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Global state normalization: Gradually prefer tighter fits as the stream progresses 
    // to minimize the tail-end waste.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 6. Penalty for creating new bins: Only open a new bin if the score is exceptionally low.
    if bin_residual == bin_capacity {
        // High base penalty for opening new bins
        score += 45.0;
        // Reduce penalty if existing bins are already very full (high mean_residual means low space)
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    score
