        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 40.0; // Strong disincentive to open new bins if existing ones work
        }
    } else {
        // Reward placements that result in "tight" bins (post_residual near 0)
        // Penalize bins that leave awkward gaps (1-9) which are hard to fill later
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Lookahead heuristic: If the next item fits into the current post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // Dynamic pressure: If we have many open bins, penalize bins that increase mean_residual
        // to encourage consolidating items into fuller bins.
        if open_bins_count > 5 {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    // Safety valve: Ensure we don't return negative scores that might break logic, 
    // though the objective is relative ordering.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
