    // Lookahead penalty: if the next item is large and the post_residual is too small to accommodate it,
    // we should favor bins that leave larger residuals or bins that are already well-suited.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Reward bins that have a residual close to the mean, promoting uniform bin usage.
    let variance_penalty = (post - mean_residual).abs() * 0.2;

    // Final score: lower is better. 
    // We combine the base efficiency, the dynamic new-bin penalty, and the lookahead context.
    fit_efficiency + new_bin_penalty + lookahead_penalty + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit strategy)
    // We prioritize bins that leave the least space.
    score += post_residual as f64 * 0.1;

    // 2. Harmonic Class Logic: Penalize "Fragmented" remainders.
    // If post_residual is small but not zero, it's often a "dead zone" that cannot fit future items.
    // We penalize remainders that are smaller than the smallest likely item (10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Synergy: Can the next item fit perfectly into the new post_residual?
    // If next_item_size fits exactly or leaves very little slack, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0; // Strong reward for perfect packing
        } else if slack < 10 {
            score -= 20.0; // Moderate reward for tight packing
        }
    }

    // 4. Thresholding New Bins:
    // Only open a new bin if the current bin's mean_residual is consistently high,
    // indicating we are wasting space across the board.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -1000.0; // Mandatory opening
        } else {
            // Apply a heavy penalty to opening a new bin if we have fitting options
            // unless the mean_residual is very high (meaning current bins are mostly empty).
            score += 150.0 + (mean_residual * 2.0);
        }
    }

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
