    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the post_residual can perfectly fit the next item, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 / (1.0 + diff));
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless the current fit is terrible.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low, 
        // suggesting we are running out of space in existing bins.
        if mean_residual > 25.0 || fitting_bins_count == 0 {
            score += 15.0; 
        } else {
            score += 60.0; // High penalty to force reuse of existing bins
        }
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // significantly lower the score to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global density adjustment: As the stream progresses, become more aggressive 
    // about packing into tighter spaces.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
