        base_cost + (open_bins_count as f64 * 2.0) - (progress * 10.0)
    } else {
        0.0
    };

    // Factor in the mean residual: if we are creating a bin with a residual 
    // significantly higher than the average, it is likely suboptimal.
    let deviation_penalty = (post - mean_residual).max(0.0) * 0.8;

    // Combine terms:
    // 1. post: Baseline preference for Best-Fit (smaller post is better).
    // 2. dead_space_penalty: Avoid fragments.
    // 3. lookahead_alignment: Prefer slots that fit the next item.
    // 4. new_bin_penalty: Control bin creation.
    // 5. deviation_penalty: Keep bin residuals consistent.
    post + dead_space_penalty + lookahead_alignment + new_bin_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A lower post_residual is usually good (Best Fit), but we want to avoid 
    // creating "dead space" that cannot fit future items.

    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Penalize post_residuals that are small but unusable.
    // If post_residual is < 10, it is likely "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead coupling: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Fitting scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // 4. Global efficiency: If we have many open bins, penalize opening new ones.
    // bin_residual == bin_capacity represents the "New Bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage opening a new bin if we are near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    }

    // 5. Harmonic balance: Favor bins that stay close to the current mean residual
    // to keep the packing density uniform across all active bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

