        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward filling bins that are near the mean residual to keep distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Last Chance Logic: If this is the only bin that fits, heavily prioritize it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progress Normalization: As we reach the end of the stream, prioritize closing bins
    // by preferring smaller post_residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

