        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5; // Moderate penalty for over-shooting
        } else {
            score += 20.0; // Penalty if next item cannot fit in this residual
        }
    }

    // 3. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // only pick it if fitting_bins_count is low or residuals are very poor.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
