        score = 80.0 + (fitting_bins_count as f64 * 10.0);
    } else {
        // 4. Tightness bias: 
        // Penalize residuals that are too small to be useful for common items (e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // 5. Global state normalization:
        // Favor bins that align with the current mean_residual to keep density uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Progress factor: Be more conservative (tighter) as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize post_residual, so it naturally acts as a base cost.

    // 2. Lookahead Integration: If the next item can fit in the current post_residual,
