    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit any common item
    // (e.g., < 10), it's "dead space". Penalize this heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // 4. Global State Awareness: If we have many open bins, prioritize filling existing ones.
    // As the stream progresses, become more aggressive about minimizing open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count > 0 {
