    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the fit in existing bins is truly terrible (high post_residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
