        score += progress * 30.0;
    }

    // 6. Scarcity Constraint: If this is the only bin that fits the current item, 
    // heavily incentivize using it to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Balance against Mean Residual:
    // Prefer bins that keep the average residual closer to a "healthy" value (e.g., 20).
    // This helps prevent packing everything into one bin and leaving others empty.
    let target_mean = 20.0;
    score += (post_residual as f64 - target_mean).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == capacity) as the stream progresses
    // to force tighter packing in existing bins late in the lifecycle.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        15.0 + (progress * 45.0) 
    } else {
