    };

    // Non-linear coupling: Favor bins that leave small residuals, 
    // but penalize residuals that are too small to fit common future items (e.g. < 10).
    // The "Sweet Spot" is around 10-20 remaining space.
    let residual_efficiency = if post < 10.0 {
