    } else {
        0.0
    };

    // Aggregate score: Lower is better.
    // We balance the absolute residual size with the penalty for opening new containers
    // and the potential for future fitment.
    let score = post + residual_efficiency + new_bin_penalty + lookahead_mod;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
