    // If post_residual is small but > 0, it's often unusable. Penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global state awareness:
    // If we have many open bins, prioritize closing/filling existing ones (Best Fit)
    // If we have very few, be more conservative about packing density
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 5. New Bin penalty:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless we have no other choice or the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 6. Harmonic/Modulo bias:
    // Prefer bins that align with common item sizes (e.g., 25, 33, 50) 
    // to keep the bin_residual a multiple of common factors.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 7. Last chance heuristic:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
