    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can take the item
            score += 120.0 * (1.0 - progress);
        }
        // Early in the stream, we are more lenient with new bins to keep residual capacity high
        score += 10.0 * progress;
    }

    // 5. Dynamic balancing: Avoid creating bins with very low residual averages
    // If the mean_residual is high, we are "wasting" space globally, so prefer tighter fits
    if mean_residual > 30.0 && post_residual > 20 {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Final constraint: If this is the only bin that fits, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space; we penalize large gaps to favor Best-Fit.
    let mut score = post;

    // Non-linear coupling: As the stream progresses, we become more aggressive about 
    // packing small items tightly into existing bins to avoid creating "orphaned" 
    // large residuals that cannot be filled later.
    let tightness_penalty = (post.powf(1.5)) * (1.0 - progress);
    score += tightness_penalty;

    // Lookahead logic: If the next item is large, penalize residuals that are 
    // smaller than the next item to prevent premature bin exhaustion.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powf(1.2);
        }
    }

    // New Bin Heuristic: When deciding to open a new bin (bin_residual == bin_capacity),
    // we calculate the cost of opening based on the average residual of existing bins.
    // We only open a new bin if the current open bins are already "too full" to 
    // accommodate future items effectively.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream.
        // Penalty decreases as the density of existing bins increases (mean_residual).
        score += (bin_capacity as f64) * (1.0 - progress) * (1.0 + (mean_residual / bin_capacity as f64));
    } else {
        // Reward bins that keep the mean_residual high, as they are more flexible for future items.
        score -= (post - mean_residual).abs() * 0.5;
    }

    // Final correction: Heavily penalize bins that are "last chance" (fitting_bins_count == 1)
    // if the resulting post_residual is highly suboptimal for the specific item_size.
    if fitting_bins_count == 1 && post > 0.0 && post < 10.0 {
        score -= 50.0; // Force the use of the last remaining fit bin to save space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20)
    // We prioritize bins where the post_residual is either 0 (perfect fit) 
    // or large enough to accommodate the next item.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic class logic: penalize residuals that are not multiples of common item sizes (20, 25, 50).
    // This helps consolidate remaining space for future packing.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    // If this is the only bin that can fit the item, we are forced to take it.
    // We lower the score significantly to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // If considering a new bin (bin_residual == bin_capacity), apply a penalty 
    // based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);

        // If there are other bins that could have fit this item, make opening a new one very expensive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Adjust for stream progression: as we near the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (mean_residual * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items
    // but too large to be considered "packed tight". 
    // Small gaps (1-9) are often "poisoned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin heavily to keep the bin density high.
    if next_item_size > 0 && post_residual >= next_item_size {
