    }

    // Lookahead: Reward placements that make the post_residual a perfect fit for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // High reward: perfect future fit
        } else if post_residual > next_item_size {
            // Slight reward if the post_residual remains "useful" (can fit the next item)
            score -= 5.0;
        }
    }

    // Balancing: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 20.0;
    }

    // Avoid opening new bins unless necessary: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it relative to fitting_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64 * 5.0);
    }

    // Global optimization: favor keeping residuals close to the population mean to maintain homogeneity
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit strategy)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for any likely future item
    // If post_residual is small but > 0, it's often better to have a larger residual
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next item exists, favor bins that can accommodate it later
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 10.0; // Penalize bins that will definitely require a new bin for the next item
        }
    }

    // Global state optimization: discourage opening new bins if there are ample open bins
    if is_new_bin {
        score += 40.0 * (1.0 - progress); // Heavily penalize new bins early in the stream
        score += (open_bins_count as f64) * 2.0; // Discourage fragmentation
    } else {
        // If this is the only bin that fits, prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Reward bins that stay close to the global average residual to maintain uniformity
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Reward bins that leave very little space (Best Fit)
    // Penalize large post_residual quadratically to avoid "fragmentation"
    let mut score = post.powi(2) * 0.1;

    // Lookahead: If the next item can fit in the current post_residual, 
    // significantly favor this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
    }

    // Dynamic threshold for opening a new bin:
    // As the stream progresses, become increasingly conservative about opening new bins.
    // If it's a new bin (bin_residual == bin_capacity), add a penalty that grows 
    // with progress to force utilization of existing bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Heuristic for "Last Chance": If this is the only bin that can fit the item,
    // lower the score to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Coupling with mean_residual: penalize bins that deviate negatively from the mean,
    // encouraging a uniform distribution of fill levels across open bins.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: prioritize smaller post_residual
    // 2. Penalty for creating "dead space": if post_residual is in the range [1, 9], 
    //    it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead logic: if the next item can fit in the current post_residual, 
    //    heavily reward this bin to keep the next step efficient.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple 
    //    of common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 5. Open bin management: If this is the last fitting bin, penalize it slightly 
    //    to force consideration of a new bin if the current fit is poor (Best Fit).
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    // 6. Global progression: As we approach the end of the stream, prioritize 
    //    filling existing bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // 7. New bin penalty: If the bin is empty (new bin candidate), add a base cost.
    //    This makes the heuristic prefer existing bins unless the fit is truly awful.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
