    // 4. Mean residual alignment: Avoid bins that deviate significantly from the average state.
    // This helps maintain a uniform fill rate across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. New bin penalty: If this is an empty bin, apply a heavy penalty unless the 
    // current fitting bins are all "poor" fits (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Necessary to open the first bin
        } else {
            // Only open a new bin if the current options are very poor (high post_residual)
            score += 45.0; 
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
