    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Bin Pressure: Penalize opening new bins when many are already open,
    // but reward using existing bins to keep the count low.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize based on how many bins are already active.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // This is an existing bin. Reward using it to reduce open_bins_count.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Residual Balancing: If the bin is becoming very empty, penalize it to encourage packing tighter.
    if post_residual > (bin_capacity / 2) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // Base score is already post_residual.

    // 2. Lookahead Synergy: Reward bins where the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong incentive: perfectly or near-perfectly fitting the next item.
            score -= 45.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalty: creating a "fragment" that cannot fit the next item.
            score += 15.0;
        }
    }

    // 3. Mean Alignment: Penalize bins that deviate significantly from the average residual,
    // as they likely represent sub-optimal filling patterns.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. Scarcity/Efficiency Logic:
    // If this is the only bin that fits, we are forced to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0; 
    }

    // 5. New Bin Control: 
    // If the bin is new, impose a high cost unless the current item is large 
    // or the packing efficiency is exceptionally poor.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin.
        score += 55.0;
        // If the item itself is very large, reduce the penalty for a new bin.
        score -= (item_size as f64) * 0.4;
    }

    // 6. Progressive Tightening:
    // As the stream nears completion, become more aggressive in packing to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize post_residual to pack bins tightly
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As we progress through the stream, we become more conservative about opening new bins.
    if is_new_bin {
        score += 25.0 * (1.0 + progress);
    }

    // Lookahead logic:
    // If we have a next item, check if it fits in the current post_residual.
    // If it fits perfectly or very well, prioritize this bin (negative bias).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_waste = post_residual - next_item_size;
            // Reward bins that can accommodate the next item with minimal slack
            score -= (50.0 - space_waste as f64) * 0.5;
        } else {
            // Penalize bins that leave just enough space for nothing (fragmentation)
            if post_residual < 15 {
                score += 15.0;
            }
        }
    }

    // Global state adjustment:
    // If we have many open bins, prioritize packing into existing ones to close them.
    // If fitting_bins_count is 1, this is the only bin that can take this item.
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Penalize bins that deviate too far from the mean residual (standardization)
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating small, unusable gaps (1..10) that are difficult to fill later.
    // We increase penalty as the stream progresses, as recovery becomes harder.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic threshold for opening a new bin:
    // If the bin is brand new (residual == capacity), we only pick it if it's 
    // impossible to fit the item well in existing bins.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by total items remaining.
        score = 25.0 + (10.0 * (1.0 - progress));

        // If there are many fitting bins, strongly discourage opening a new one.
        score += fitting_bins_count as f64 * 5.0;
    } else {
        // Encourage packing into bins that are already partially filled to keep 
        // the number of open bins low, weighted by mean_residual.
        score += (mean_residual - post) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want the post_residual to be as small as possible (tight packing).

    // 2. Lookahead Penalty: If this placement creates a post_residual that cannot fit the next item,
    // but the next item could have fit if we chose a different bin, penalize heavily.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 3. Harmonic/Modulo optimization:
    // Favor residuals that are multiples of common item sizes or leave "clean" remainders.
    // This reduces fragmentation by keeping remaining space usable for common patterns.
    score += (post_residual % 10) as f64 * 0.5;

    // 4. New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on current fragmentation.
    // If we have many open bins with plenty of space, opening a new one is inefficient.
    if bin_residual == bin_capacity {
        score += 35.0; // Base cost to open a new bin
        score += (open_bins_count as f64) * 2.0; 
        score -= mean_residual * 0.2;
    }

    // 5. Critical thresholding:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // strongly prefer it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, prioritize tightest fits to clear out open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
