    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin, apply a heavy penalty based on current open bin density.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If next_item_size is known, penalize bins that 
    // would prevent the next item from fitting comfortably.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
