    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Balancing: Prefer bins closer to the global mean to 
    // keep bin contents uniform, preventing "outlier" bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to prevent premature bin opening.
    // We only open a new bin if the existing fits are extremely inefficient.
    if bin_residual == bin_capacity {
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // 2. Best-Fit logic: prioritize bins where post_residual is minimized.
        // Penalty for creating 'dead space' that is too small for common items.
        if post_residual < 10 {
            score -= 15.0; // Reward perfect/near-perfect closure
        } else if post_residual > 50 {
