    let mut score = post;

    // Penalty for creating a 'dead zone' (residual space too small for any likely future item).
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, prioritize bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize this bin.
    if next_item_size > 0 && post < next_item_size as f64 {
