    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - (progress * 0.5));

        // If we have many open bins, opening a new one is highly discouraged unless necessary.
        score += (open_bins_count as f64) * 2.0;
    }

    // Encourage density: penalize bins that deviate significantly from the mean residual.
    // This helps keep bins balanced in their utilization.
    score += (post - mean_residual).abs() * 0.5;

    // Favor bins that become "full" (post_residual == 0) as progress increases.
    if post == 0.0 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

