}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_sq = post_res * post_res;

    // Penalize creating small, unusable gaps (1-9) heavily, especially early in the stream.
    // As progress approaches 1.0, favor tighter packing to finish the stream.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_residual as f64) * 20.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Factor in lookahead: if next_item_size fits in the current post_residual, 
    // prioritize this bin to keep the packing density high.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 + progress)
    } else {
        0.0
    };

    // If this is the last fitting bin, we are forced to use it unless we open a new one.
    // Penalize opening a new bin (where bin_residual == bin_capacity) unless 
    // the post_residual in existing bins is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if open_bins_count == 0 { 0.0 } else { 45.0 - (progress * 10.0) }
    } else {
        0.0
    };

    // Non-linear coupling: Balance the raw residual with the mean_residual of open bins.
    // We want to avoid bins that deviate significantly from the average residual.
    let deviation_penalty = (post_res - mean_residual).abs() * 0.5;

    // Final score: lower is better.
    // We favor smaller post_residual (tighter fit) but penalize tiny gaps.
    res_sq * 0.01 + gap_penalty + lookahead_bonus + new_bin_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
