    //    If this is a new bin (bin_residual == bin_capacity), make it expensive 
    //    unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 50.0; // Heavily discourage opening new bins if existing ones work
        } else {
            score -= 20.0; // Neutralize the cost if we are forced to open a new bin
        }
    }

    // 6. Mean Residual Balancing: 
    //    If the current bin's post_residual is significantly better than the global mean, 
    //    incentivize it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "wasteland" potential by penalizing small post_residuals 
    // that are too small to fit common items (10-30), while accounting for 
    // the cost of opening new bins.

    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are hard to fill.
    // If post_residual is in (0, 10), it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if next_item_size is large and won't fit in post_residual,
    // we want to preserve this bin's space for it if possible.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
