    // We only want to open a new bin if the current open bins are already very full.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many empty/half-full bins.
        score += (open_bins_count as f64) * 5.0;
        score += mean_residual * 0.5;
    } else {
        // Reward filling existing bins to keep open_bins_count low.
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // If this is the last chance for the current item, prioritize it slightly
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
