        }
    }

    // Penalty for increasing the number of active bins, scaled non-linearly
    score += (open_bins_count as f64).powf(1.2);

    // Coupling: interaction between mean_residual and current post_residual
    // Helps maintain a uniform fill across all bins.
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
