    // 3. Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that create a perfect fit for the next item
            if post_residual == next_item_size {
                score -= 20.0;
            }
        }
    }

    // 4. Fitting scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the 
    // average state of the system to maintain uniform packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about fitting items into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small gaps (1-9) that are difficult to fill
    // later, while rewarding tight fits (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    } else if post_residual == 0 {
        score -= 10.0;
