    // 2. Lookahead optimization: If the next item can fit in this bin, prioritize it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open bin pressure: If this is a new bin (bin_residual == bin_capacity),
    // penalize opening it if we have other options, but reduce penalty as the
    // stream progresses to avoid packing inefficiency at the end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let openness_penalty = (open_bins_count as f64 * 5.0) * (1.0 - progress);
        score += 30.0 + openness_penalty;
    }

    // 4. Fitting constraints: If this is the only bin that fits the item,
    // reduce the score to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global state balancing: Avoid creating bins with residuals significantly 
    // smaller than the current mean residual to maintain packing density.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

