    // 3. New Bin Thresholding: Discourage opening a new bin unless existing 
    // bins are very poorly suited (i.e., high mean_residual relative to item_size).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // Must open new if nothing else fits
        } else {
            // Heavily penalize opening a new bin if we have flexible options
            score += 150.0 - (mean_residual * 1.5);
        }
    }

    // 4. Density Balancing: If we are near the end of the stream, 
    // prioritize clearing out the most fragmented bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item,
    // ensure it is prioritized.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
