    score += (post_residual as f64) * 0.1;

    // Criticality check: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual alignment: Avoid bins that deviate significantly from the average occupancy.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residual values that are between 1 and 9, 
    // as these are often too small for the minimum item size (10).
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead interaction: If the next item is large, avoid leaving a residual that 
    // is slightly too small to fit it (e.g., if next_item is 50, avoid residual of 40).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 && gap < 20.0 {
            score += 40.0 * (1.0 - (gap / 20.0));
        }
    }

    // Adaptive pressure: As the stream progresses, tighten the constraint on opening new bins.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low,
        // but scale this by progress to allow more flexibility early on.
        let openness_penalty = (open_bins_count as f64 * 0.5) * (1.0 + progress);
        score += 25.0 + openness_penalty;
    } else {
        // Reward bins that keep the mean residual balanced relative to the remaining capacity.
        // This helps prevent "bin fragmentation".
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Heuristic coupling: discourage leaving a bin nearly empty if it could have been filled better.
    // We weight this influence by the remaining stream progress.
    score += (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
