    };

    // Global efficiency term: Penalize opening a new bin if we have plenty of open bins.
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (progress * 50.0)
    } else {
        0.0
    };

    // Coupling: If fitting_bins_count is 1, this is the only bin that can take the item.
    // We heavily discount the score to force selection of existing bins over new ones.
    let urgency_discount = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -1000.0
    } else {
