    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Pressure: penalize opening new bins as the stream progresses
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 20.0) + (open_bins_count as f64 * 2.0);
    }

    // If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty for increasing the variance of bin usage (if bin_residual is significantly worse than mean)
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual while prioritizing slots that perfectly accommodate the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals that are smaller than the smallest likely item (e.g., < 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. 2-step lookahead: Reward bins that become "perfect fits" for the next item.
    // If post_residual is exactly next_item_size, we favor this bin heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // 3. Pressure to consolidate: If we have many open bins, penalize opening a new one 
    // unless the fit is exceptionally good.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalize opening a new bin if other bins exist
            score += 30.0 + (open_bins_count as f64 * 2.0);
        }
        // If it's the only option, reduce penalty
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // 4. Mean residual alignment: Favor bins that bring the current bin's residual 
    // closer to the global mean residual of open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Near-exhaustion bonus: If this bin is the last chance for the current item,
    // and it leaves a large space, penalize it slightly to force use of tighter bins.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Penalty for creating "dead space": post_residual values that are too small for common items
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // 4. Global State: If we have many open bins, prioritize tightening existing bins.
    // If we have few open bins, prioritize keeping future flexibility (higher mean_residual).
    let bin_density_factor = (open_bins_count as f64) * (1.0 - (mean_residual / bin_capacity as f64));
    score += bin_density_factor * 2.0;

    // 5. Thresholding: Avoid opening a new bin unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only pick if fitting_bins_count is 0 or if all current fits are very poor.
        if fitting_bins_count > 0 {
            score += 40.0 + (progress * 20.0);
        } else {
            score -= 10.0;
        }
    }

    // 6. Final adjustment: Encourage filling bins that are already "half-full" 
    // to keep the number of active bins manageable.
    if bin_residual < 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to leave it slightly larger to accommodate future items.
    // We penalize very small residuals (1-9) as they are likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 2.5;
    }

    // Lookahead coupling: if the next item is large, prioritize bins that can accommodate it.
    // If the next item is larger than current post_residual, we penalize this bin.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Progression weighting: As the stream nears the end, become more aggressive 
    // about filling existing bins to prevent leftover items from requiring new bins.
    let exhaustion_factor = 1.0 - progress;
    score *= 1.0 + (exhaustion_factor * 0.5);

    // New-bin logic: If this is a new bin (bin_residual == bin_capacity), 
    // add a penalty proportional to the number of open bins to discourage proliferation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.2);
    }

    // Fitting count incentive: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
