    // 2. Harmonic/Modulo Logic: Penalize remainders that are "awkward" sizes.
    // Small remainders (< 10) are often useless; larger remainders are better if they fit common item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Strong penalty for "fragmentation" creating unusable slivers.
    }

    // 3. Lookahead Integration: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
