    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0; 
    }

    // 5. Empty Bin Threshold: Heavily penalize opening a new bin unless the current
    // fits are extremely poor (i.e., very high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low,
        // or if we are early in the stream.
        score += 30.0 + (mean_residual * 0.2);
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

