    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < next_item_size {
            // Penalize if the next item won't fit here, but only if it's not a new bin.
            if !is_new_bin {
                score += 20.0;
            }
        }
    }

    // 3. Global State Dynamics:
    // If we are nearing the end of the stream, prioritize packing tightly.
    // Otherwise, keep bins slightly more open to accommodate larger items later.
    if progress > 0.8 {
        score -= (100 - bin_residual) as f64 * 0.1;
    }

    // 4. New Bin Logic:
    // Discourage opening new bins unless the current options are poor.
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 35.0;

        // If there are other bins that could fit this item, make opening a new one very expensive
        if fitting_bins_count > 0 {
            score += 60.0;
        }

        // If current bins are mostly empty, opening a new one is inefficient
        if mean_residual > 50.0 {
