}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle).
    // Penalize creating small, unusable gaps (1-9) heavily, especially early in the stream.
    let gap_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * 5.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead logic: If a bin can fit the next item, reward it.
    // Avoid opening new bins unless the fit is very poor or we are near the end.
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -(post - next_item_size as f64).sqrt() * 2.0
    } else {
        0.0
    };

    // Penalty for opening a new bin when existing options are available.
    let new_bin_penalty = if bin_residual == bin_capacity && open_bins_count > 0 {
