    } else {
        0.0
    };

    // Interaction between mean residual and current state: 
    // Discourage fragmentation by penalizing bins that deviate significantly from the mean.
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: Lower is better.
    post + gap_penalty + lookahead_bonus + new_bin_penalty + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
