    };

    // Balance residual minimization with the desire to keep bins "open-ended" for later
    // We favor mid-range residuals slightly as the stream progresses to handle late-game packing
    let score = post + fragmentation_penalty + lookahead_bonus + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
