        score -= 25.0;
    }

    // Global density adjustment: penalize deviations from the mean residual to keep bins uniform.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (very small residual) that is unlikely to fit future items.
    // We prioritize bins that leave larger residuals or zero residuals (perfect fit).
    if post_residual > 0 && post_residual < 10 {
