    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Discourage opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Coupling: If the next item exists, penalize placements that prevent the next item from fitting.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if this placement forces a new bin for the next item
            score += 15.0;
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it to avoid fragmenting the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Mean Residual Alignment: Favor bins that keep the overall mean residual stable, 
    // preventing extreme variance in bin utilization.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
