        let secondary_residual = post_residual - next_item_size;
        if secondary_residual < 5 {
            score -= 10.0;
        }
    }

    // 3. Pressure management: If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5);
