    // Reward bins that maintain a residual close to the mean, promoting balanced packing.
    let balance_reward = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, penalize small post_residuals 
    // that won't be able to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // Special handling for new bins:
    // Only open a new bin if the current fit is extremely poor (post_residual > 40)
    // or if we are near the end of the stream and need to clear space.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary to open
        } else {
            45.0 + (progress * 20.0) // Increase cost to open new bin as stream progresses
        }
    } else {
        0.0
    };

    let mut score = post_res + dead_zone_penalty + balance_reward + lookahead_penalty + new_bin_base;

    // Penalize opening too many bins early on
    if is_new_bin && open_bins_count > 0 {
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

