    // 2. Harmonic Class Logic: Reward residuals that align with common item size patterns.
    // If post_residual is a multiple of 20, it is likely to accommodate common medium items.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Fragmentation Control: Avoid creating "dead" space (residuals < 10) unless necessary.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // 4. New Bin Thresholding: Dynamic bias against opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty based on open_bins_count.
    if bin_residual == bin_capacity {
