    }

    // 6. Fitting Pressure: If this is the only bin that fits the current item, lower its score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 7. Progression scaling: As we approach the end of the stream, prioritize bin exhaustion.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

