    score += (open_bins_count as f64).powf(1.1) * 0.5;

    // Favor bins that are already "near-full" to keep the number of active bins low.
    // We reward placements that leave a residual close to the mean_residual of existing bins.
    let residual_diff = (post - mean_residual).abs();
