    // If we are late in the stream, favor using open bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as the stream progresses.
        score += 40.0 + (progress * 60.0);
    }

    // 5. Density Reward:
    // Reward packing into bins that are already "half-full" or more to keep the 
    // number of active open bins (open_bins_count) low.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.5 {
        score -= 10.0;
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
