        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item doesn't fit in the remaining space, 
    // prioritize bins that leave exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that block the next item from fitting
            score += 20.0;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward bins that "perfectly" accommodate the next item (tight fit)
            score -= 15.0;
        }
    }

    // Dynamic pressure: As we approach the end of the stream, prioritize closing bins
    // by penalizing the opening of new bins (represented by bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + (progress * 40.0);
    }

    // Penalty for increasing the total number of active bins unnecessarily.
    // We prefer to keep the number of open bins low to maintain high density.
    score += (open_bins_count as f64) * 2.0;

    // Favor bins that are already closer to being full (lower post_residual is good, 
    // but here we weight the existing mean_residual to balance the bin load).
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

