    // 5. Mean Residual Alignment: If this bin's post_residual is significantly better
    // than the current mean, reward it to consolidate space usage.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Scarcity Adjustment: If this is the only bin that can fit the item,
