    // Dynamic balancing: As the stream nears the end, prioritize filling
    // existing bins over opening new ones, even if the fit is suboptimal.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalty for opening a new bin: scales with progress
        score += 40.0 + (progress * 60.0);
    }

    // Influence of current mean residual: If our current bins are mostly empty,
    // we should favor bins that bring the mean closer to a target density (e.g., 20-30 left).
    let deviation_from_target = (mean_residual - 25.0).abs();
    score += deviation_from_target * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space (too small for most items)
    // We penalize post_residual values that are likely to become unusable (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, favor bins that can accommodate it later
    // If post_residual is less than the next item, we penalize it heavily
    if next_item_size > 0 {
        if post_residual < next_item_size {
