    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one
    // New bins have bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin is scaled by the progress of the stream
            let progress = step_index as f64 / total_items as f64;
            score += 40.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Fitting constraints: If this is the last chance for this item, prioritize it
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Residual Smoothing: Penalize deviations from the mean_residual
    // This encourages keeping bins at similar fullness levels (Best Fit variation)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
