            score += 20.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it
    // compared to the average efficiency of currently open bins.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high to encourage packing into existing ones
        let mut new_bin_cost = 45.0;

        // As we reach the end of the stream, the cost of opening a new bin increases
        // to force consolidation into existing bins.
        new_bin_cost += 30.0 * progress;

        // If we have many open bins that are nearly empty, penalize opening another.
        new_bin_cost += (open_bins_count as f64) * 2.0;

        score = new_bin_cost;
    } else {
