        // to ensure we don't open a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Penalize bins that deviate too far from the mean_residual (maintains balanced filling)
        let deviation = (residual - mean_residual).abs();
        score += 0.5 * deviation;
    }

