    // be more aggressive about filling existing bins rather than opening new ones.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        // Penalty for opening a new bin when existing ones are available
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Dead Space Avoidance: If post_residual is small (e.g., < 10) but > 0, 
    // it creates "unusable" space. Penalize this specific range.
    if post_residual > 0 && post_residual < 10 {
