    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 2. Best-Fit logic: Prefer bins that leave the least space (lower post_residual)
    // 3. Lookahead: If post_residual is very close to next_item_size, reward this bin
    // to create a "perfect" follow-up fit.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // Reward cases where next item fits perfectly
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Global balance: If this bin's residual is significantly lower than the mean, 
    // it's a tight bin. Avoid making it even tighter if it risks stranding items.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    // 5. Urgency: As we near the end of the stream, prioritize closing bins (lower score)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Penalty for creating "dead zones" (bins with very little space but too small for average items)
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // We prioritize bins that result in a tight fit (low post_residual)
    // while heavily penalizing the creation of "dead space" (small, unusable residuals).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space after placement.
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable space < 10, since min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Heuristic: If we are near the end of the stream, encourage tighter packing.
    if progress > 0.8 {
        score *= 1.2;
    }

    // Lookahead logic: if we know the next item, penalize bins that can't fit the next item
    // if this bin is currently the only one that could potentially fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // If this is a new bin, apply a significant penalty to encourage using existing bins.
    // The penalty scales with the number of open bins to prevent excessive bin proliferation.
    if is_new_bin {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, check if it's the last chance to fit the current item.
        if fitting_bins_count == 1 {
            score -= 20.0; // Strong incentive to use the last fitting bin.
        }
    }

    // Global state adjustment: penalize bins that deviate significantly from the mean residual
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual (Best Fit principle).
    // We want to minimize the post-residual to pack bins tightly.
    let mut score = post;

    // Penalty for creating a bin that is too small for the next item (Lookahead).
    // If we have a next item, and the current bin's post-residual is smaller than that item,
    // we penalize this bin to encourage using a bin with more space if possible.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // Dynamic pressure: As the stream progresses, penalize opening new bins 
    // more heavily to encourage consolidation.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // We add a cost that increases as we approach the end of the stream
        // to prevent opening a new bin when we should be finishing old ones.
        score += 25.0 + (progress * 50.0);
    } else {
        // For existing bins, reward bins that are closer to the mean residual
        // to keep usage balanced (prevents "fragmentation").
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;

        // If this is the last chance for the current item, prioritize it 
        // to prevent unnecessary overflow into a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear interaction: Penalize very small gaps (e.g., 1-5) as they
    // are often "dead space" that cannot fit typical items.
    if post > 0.0 && post < 6.0 {
        score += 8.0 * (1.0 - (post / 6.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
