    // 3. Global state awareness: If we have many open bins, penalize opening a new one.
    // If the bin is new (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with the number of existing open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0 * (1.0 - progress * 0.5);
    }

    // 4. Fitting constraints: If this is the last fitting bin, prioritize it 
    // to avoid leaving it underutilized if we were to open a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate too far from the average.
    // This encourages a "Best-Fit" behavior by keeping all bins at similar fullness.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin. Lower is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "slivers" (small unusable space). 
    // We penalize values between 1 and 9, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large and won't fit in this post_residual, 
    // we penalize this bin to encourage saving it for a better fit.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Encourage filling bins earlier in the stream, but be more conservative 
    // as we approach the end of the stream to avoid opening new bins.
    if bin_residual == bin_capacity {
        // This is a new bin candidate.
        // We only want to open a new bin if we have many open bins already, 
        // or if the current packing efficiency is very poor.
        score += 40.0 + (mean_residual * 0.5);
        if progress > 0.8 {
            score += 30.0; // Strong penalty for new bins near the end.
        }
    } else {
        // If this bin is the only one that fits the item, highly prioritize it.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // Reward packing into bins that are already relatively full (high density).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a small, unusable gap (fragmentation)
    // We penalize residuals between 1 and 9 specifically, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic/Modulo logic: Favor bins that leave a residual which is a multiple of larger item sizes (e.g., 20, 25, 50).
    // This helps align residuals for potential future packing of common item multiples.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // If this is the only bin that fits the current item, prioritize it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New bin avoidance: If we are considering a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the current average residual is already very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 100.0; // Must open a bin if no others exist
        }
    }

    // Efficiency bias: Favor bins that are closer to being full (lower post_residual).
    // The base score starts as post_residual, so we apply a non-linear weight.
    score += (post_residual as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps smaller than the smallest likely item (e.g., < 10)
    // if we are not finishing the bin completely (post_residual != 0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize placements that leave
    // insufficient room for the next item, forcing a new bin if the current fit is "too tight".
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if other bins are available.
    // This creates a "soft" Best-Fit behavior.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have many bins open, it's almost always better to pack into an existing one
        // unless the fit is extremely poor (high post_residual).
        if open_bins_count > 5 {
            score += 100.0;
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, prioritize smaller post_residuals
    // to maximize bin utilization density.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

