    }

    // 4. Adaptive thresholding: If the current bin is significantly tighter than the 
    // average open bin, favor keeping it tight to preserve "loose" bins for larger items.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Final stage heuristic: As the stream nears the end, prioritize filling
    // existing bins aggressively to minimize the trailing open bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
