        // If we have many open bins, penalize opening a new one
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If this is the last bin that can fit the item, reward using it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Favor bins that align with the global average residual to keep bins uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Progress ratio [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

