    }

    // Lookahead influence: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the bin slightly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // New bin strategy: Only open a new bin if the current fit is poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream.
        // We decrease this penalty as the stream progresses to allow for better packing.
        score = 45.0 + (20.0 * (1.0 - progress));

        // If no bins can fit the item, we are forced to open a new one.
        if fitting_bins_count == 0 {
