        }
    } else {
        // Favor bins that align with the global mean, reducing variance in bin residuals.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // Final scaling: favor bins that leave more space for the next item if we are late in the stream
    score -= (progress * (bin_capacity - post_residual) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // We favor bins where the residual is small (i.e., tight packing).
    // Adding post_residual is the base cost.

    // 2. Harmonic Class Logic:
    // Penalize post_residual values that create unusable gaps (dead space < 10).
    // Since item sizes are >= 10, a post_residual of 1-9 is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
