            // especially if this is the only bin that could have fit the current item.
            if fitting_bins_count == 1 {
                score += 20.0;
            }
        }
    }

    // 4. Global Density Awareness:
    // If the mean residual is high, we are being too loose. Favor tighter fits.
    // If mean_residual is low, we are being too conservative, potentially creating too many bins.
    score += (mean_residual - post_residual as f64) * 0.5;

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a new bin.
    // We heavily penalize opening a new bin unless the current fit is catastrophic.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is proportional to the number of open bins.
        // As we progress through the stream, we become more reluctant to open new bins.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 20.0) + (open_bins_count as f64 * 2.0);
    }

    // 6. Modulo Harmonic Bias:
    // Favor bins that leave room for common factor multiples (e.g., leaving 25, 50, 75).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
