    // If post_residual is between 10 and 20, it's often a "wasteland" that can't fit most things.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // Reward tight fits
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0; // Heavily penalize unusable gaps
    }

    // 2. Lookahead logic: If post_residual can fit the next item, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; 
    }

    // 3. Balance against mean_residual: Avoid opening new bins if the current 
    // bin residual is already close to the system mean (keeping packing density consistent).
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin.
        // Penalty for opening a new bin increases as we progress through the stream,
        // and is higher if we have many bins already open.
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (progress * 50.0) + (open_bins_count as f64 * 2.0);
    } else {
        // Adjust score based on how this bin's residual compares to the global mean.
        // We prefer bins that are "tighter" than the average.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Scarcity principle: If this is the only bin that can fit the item, 
    // heavily prioritize it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // We penalize residuals that are smaller than the smallest possible items (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item fits in the remaining space, prioritize that bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - progress);
    }

    // Global state awareness: if we are near the end of the stream, prioritize tighter packing
    if progress > 0.8 {
