    }

    // Incentive to close bins that are nearly full (high efficiency)
    if post_residual < 5 {
        score -= 20.0;
    }

    // New Bin Logic: Only open a new bin if the current fit is disastrous
    // or if we have very few bins open and need to preserve future flexibility.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if others are available
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // No choice, must open new bin
            score = 0.0;
        }
    } else {
        // Favor bins that align with the mean density of current open bins
        let density_diff = (post_residual as f64 - mean_residual).abs();
        score += density_diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
