pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit any likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), add a penalty proportional to current open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Tight Fit Reward: If this bin is the only one that fits the item, reward it to consolidate.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Fragmentation Avoidance: Penalize binning if it creates a residual significantly smaller than the mean.
    if (post_residual as f64) < (mean_residual * 0.5) && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to favor packing into existing bins.
    // The penalty is modulated by the number of open bins to prevent excessive fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.5);
    }

    // 2. Lookahead matching: Penalize the gap if it is too small to fit the next item, 
    // but reward if it creates a "perfect fit" for the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly (residual gap minimization).
            let gap_penalty = (post_residual - next_item_size) as f64;
            score += gap_penalty * 0.5;
        } else {
            // Penalize bins that render themselves unable to fit the next item.
            score += 15.0;
        }
    }

    // 3. Last chance heuristic: If only one bin fits, prioritize it heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Tightness constraint: Penalize bins that deviate significantly from the mean residual
    // to keep the packing density consistent across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress); 
    }

    // 3. Fragmentation Penalty: Penalize tiny residuals that cannot fit most items (10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 4. Strategic New Bin Opening:
    // Avoid opening new bins unless necessary (fitting_bins_count == 0)
    // or if the current bin's mean residual is already very low (high fragmentation).
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 10.0; // Necessary to open
        } else {
            // Heavily penalize opening a new bin if an existing one can fit the item
            score += 85.0 + (mean_residual * 0.5);
        }
    }

    // 5. Dynamic Density Adjustment:
    // As we approach the end of the stream, prioritize closing bins over packing efficiency
    if progress > 0.9 {
        score -= (open_bins_count as f64) * 0.2;
    }

    // 6. Global State Coupling:
    // If the mean residual of current bins is high, prefer bins that bring us closer to that mean
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers" (unusable space < 10)
    // We penalize post_residual values in the range [1, 9] heavily,
    // as they are unlikely to fit future items (min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: if the next item is large, avoid leaving small residuals
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if post_res < next_f {
            score += (next_f - post_res) * 0.5;
        }
    }

    // Stream progression adjustment:
    // As we approach the end of the stream, prioritize filling existing bins
    // over opening new ones. New bins are penalized increasingly as progress -> 1.0.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress);

        // If we are forced to open a new bin, do it only if no other good options exist.
        if fitting_bins_count > 0 {
            score += 100.0 * progress;
        }
    }

    // Balancing: Favor bins that stay close to the current mean residual
    // to keep the bin distribution uniform.
    let diff_from_mean = (post_res - mean_residual).abs();
    score += 0.2 * diff_from_mean;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tightly packed.
    // 2. Harmonic Class Logic: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25) 
    // to leave "clean" space for future items.
    let remainder_penalty = (post_residual % 25) as f64 * 0.5;
    score += remainder_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
        // Further refine: If the next item fits perfectly (waste=0), give it supreme priority.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 4. Strategic New Bin Avoidance: 
    // If this is an empty bin (bin_residual == bin_capacity), penalize opening it unless necessary.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can fit the item.
            score += 150.0;
        } else {
            // Neutralize score for unavoidable new bin.
            score = 50.0;
        }
    }

    // 5. Progression Scaling:
    // As the stream nears completion, become more aggressive in filling bins to avoid leaving items stranded.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual to prevent "fragmentation" of bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, 
    // but penalize gaps that are too small to fit common items (10-30 range).

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is between 1 and 9, it's effectively 
    // unusable for any future item, so we penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item is large, avoid leaving a residual 
    // that is just slightly too small to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Pressure management: If we have many open bins, penalize opening a new one
    // unless the fit is perfect (Best Fit logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current open bins are very full (mean_residual is small)
        // or if we have very few bins open currently.
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // Favor bins that are already partially full to consolidate space.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Critical threshold: If this is the last chance to fit an item into an existing bin
    // (fitting_bins_count == 1), give it a significant bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest post_residual.
    // Penalty for creating a new bin: if not the only option, discourage opening a new bin unless post_residual is very high.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; 
    }

    // 2. Lookahead optimization: If next_item_size fits in the current post_residual, 
    // heavily reward this bin to keep the packing tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Fragmentation mitigation: Penalize bins where the post_residual is small but unusable
    // (e.g., < 10, since min item size is likely around 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean-alignment: If the bin's resulting residual is significantly higher than the 
    // current mean, penalize it to encourage balancing the load.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency factor: As we approach the end of the stream, prioritize 
    // finishing off bins over maintaining empty space.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 6. Last-chance penalty: If this is the only bin that fits, we are forced to pick it.
    // We lower the score to ensure this bin is chosen over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor smaller post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "stranded" space: avoid leaving small gaps (1-9) that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead logic: If a next item exists, penalize bins that can't fit it after this placement
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that maintain capacity for the next item
            score -= 15.0;
        }
    }

    // Global state awareness: If we have many open bins, prioritize filling current ones (Best Fit)
    // If we have very few, be more conservative about keeping space open
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // New Bin Logic: Only open a new bin if the current fit is extremely poor (large post_residual)
    // or if the item is large and would otherwise strand significant space.
    if bin_residual == bin_capacity {
        // High threshold to open a new bin: only if existing bins are poor fits
        score = 40.0 + (mean_residual * 0.5);
    } else {
        // If it's a tight fit, drastically reduce score to favor this bin
        if post_residual < 5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: proportional to progress to discourage early waste,
    // but allow flexibility as the stream approaches the end.
    if is_new_bin {
        score += 25.0 * (1.0 - progress * 0.5);
    }

    // Heuristic: If we have multiple bins that can fit, prefer the one that leaves 
    // the smallest post_residual, but heavily penalize leaving a "dead" gap 
    // that cannot fit the next item (if known).
    if !is_new_bin && next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item
            score += 40.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Interaction with mean_residual: Encourage bins to converge toward the mean
    // to keep the packing density uniform across all active bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev_from_mean;

    // Penalty for creating too many open bins simultaneously (Fragmentation control)
    score += (open_bins_count as f64).powf(1.2);

    // Reward bins that become "tight" (post_residual near 0) more aggressively 
    // as the stream progresses, reducing fragmentation in later stages.
    if !is_new_bin {
        score -= (1.0 - progress) * (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // Base score is post_residual (already initialized).

    // 2. Penalty for creating "dead space": if the residual is small but 
    // too small to fit common items, it's wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: Try to keep space for the next item.
    // If we have a next item, penalize bins that leave less space than the next item requires.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave exactly enough space (Best-Fit-Lookahead)
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 50) to maximize packing density.
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 5. New-bin thresholding: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already that are all poorly fitted.
        // Penalty for opening a new bin is high, unless fitting_bins_count is zero.
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0;
        }
    }

    // 6. Global density regulation: If we are late in the stream, be more aggressive 
    // with packing to reduce open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that create unusable "slivers" (e.g., < 10).
    // If an item leaves a gap smaller than the minimum possible item size (10), it is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Penalize opening new bins when many are already open.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this placement to keep bins dense.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the mean residual
    // to keep the "wastage" distributed uniformly across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // We favor bins where post_residual is small, but penalize "dead space" that is too small for any future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating slivers that are unlikely to fit any item (min size 10)
    }

    // 2. Lookahead Matching: If the current post_residual perfectly matches or closely fits the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize if this choice forces a new bin for the next item
            score += 15.0;
        }
    }

    // 3. New Bin Handling
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (no other good options)
        // We set a base cost for opening a new bin that scales with how many open bins are already available
        score = 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Mean Residual Balancing
    // If the post_residual is significantly higher than the average, we are creating a "loose" bin.
    // We penalize this to encourage packing items into "tighter" bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Urgency factor
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too small for common future items
    // If post_residual is small (e.g., < 10), it's effectively "dead" space
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // Best-Fit strategy: prioritize filling bins tightly
    // We want to minimize the post_residual, but heavily penalize opening new bins 
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score = 60.0;
        // If we are near the end of the stream, opening a new bin is very expensive
        score += (1.0 - progress) * 40.0;
    } else {
        // Reward fitting into bins that are already "tight"
        // This encourages clustering small residuals together
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Lookahead: If next_item can fit in this post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dynamic constraint: If this is the last chance to fit an item (fitting_bins_count == 1),
    // and the fit is poor, we might prefer opening a new bin. 
    // We lower the score of the current bin slightly to avoid premature new bin creation.
    if fitting_bins_count == 1 && post_residual > 20 {
        score -= 10.0;
    }

    // Global state adjustment: If many bins are open, be more aggressive at filling them
    // to reduce open_bins_count.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) that are too small to fit common items
    // We use a sigmoid-like penalty for post_residual < 10
    let fragmentation_penalty = if post_residual < 10 && post_residual > 0 {
        200.0 / (post + 1.0)
    } else {
        0.0
    };

    // Incorporate lookahead: If next_item can fit in current post_residual, reward this bin
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If fitting_bins_count is 1, we are at a critical decision: pack here or open new bin.
    // If we are late in the stream (high progress), we favor packing tightly (low post_residual).
    // If early, we favor keeping residual space flexible.
    let criticality_adjustment = if fitting_bins_count == 1 {
        -20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residuals (Best Fit logic)
    // Add non-linear coupling with progress to shift from Best Fit to First Fit as stream nears end
    let base_score = post * (1.0 + 0.5 * progress);

    // If bin is empty (new bin candidate), apply a high base cost, but reduce cost as stream progresses
    // to allow opening new bins if necessary to achieve better packing efficiency
    let new_bin_penalty = if bin_residual == bin_capacity {
        150.0 - (50.0 * progress)
    } else {
        0.0
    };

    base_score + fragmentation_penalty + lookahead_reward + criticality_adjustment + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post-residuals to keep bins tightly packed.
    // However, we apply a non-linear weight to very small residuals (potential dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0; // Penalty for creating "sliver" space that is hard to fill.
    }

    // 2. Lookahead integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; 
    }

    // 3. New bin penalty: If the bin is new, only pick it if no other configuration 
    // is efficient (or if the item is large and fits poorly elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Dynamically reduce new-bin penalty as the stream progresses to reduce fragmentation.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits, we are forced to pick it.
    // We lower the score to ensure it is selected over the new-bin candidate.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Harmonic balance: Penalize bins that deviate significantly from the mean residual.
    // This helps maintain a uniform distribution of fill-levels across open bins.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Capacity utilization: Favor bins that leave very little space (Best-Fit decreasing logic).
    score += (post_residual as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

