    }

    // 5. New Bin penalty:
    // If this bin is empty (new bin candidate), add a significant penalty to discourage opening new bins
    // unless the current open bins have very poor residual scores.
    if bin_residual == bin_capacity {
        score += 35.0;

        // If we have many open bins already, make new bins even more expensive to encourage consolidation.
        score += (open_bins_count as f64) * 2.0;
