    // about opening new bins. We penalize the "new bin" case (bin_residual == bin_capacity)
    // proportional to the current open_bins_count.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item, 
    // we strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate too far from the average 
    // performance of current bins to encourage uniform packing.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely item (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
