    }

    // 4. Efficiency normalization: Favor bins that align with the global mean
    // This helps keep bins packed similarly to avoid fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (small remaining space)
    // Small slivers (1-9) are usually unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If next item is large, prioritize keeping space available
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for blocking the next item from fitting in this bin
            score += 30.0 * (1.0 - progress);
        } else {
            // Reward for preserving space for the next item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // 3. Global Bin Management: Avoid opening new bins if possible, unless the current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we are forced to or if existing bins are very fragmented
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Accept new bin if no other choice
        }
    }

    // 4. Density Balancing: Favor bins that align with the global mean residual
    // This helps maintain a uniform distribution of fill levels across bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Final Stage Optimization: As the stream ends, ignore "perfect fit" and just pack
    if progress > 0.9 {
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize wasted space.
    let mut score = post_res;

    // Penalty for leaving a bin "too empty" early in the stream, 
    // but reward it slightly if we are near the end (to clear out buffers).
    let emptiness_penalty = (bin_capacity as f64 - post_res).powi(2) * (1.0 - progress);
    score += emptiness_penalty * 0.05;

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // heavily unless it's the only option or progress is very high.
    if bin_residual == bin_capacity {
