    }

    // Lookahead interaction: If the next item is large, avoid leaving a residual
    // that is just slightly too small to fit it.
    if next_item_size > 0 {
        let fit_gap = post_res - next_item_size as f64;
        if fit_gap < 0.0 {
            // This bin will likely not fit the next item. Penalize this bin
            // if it leaves a "useless" residual gap (e.g., 1-9 units).
            if post_res < 10.0 {
                score += 50.0;
            }
        } else {
            // Reward bins that leave exactly enough space for the next item.
            score -= (1.0 / (1.0 + fit_gap)) * 20.0;
        }
    }

    // Encourage packing into bins that are already "near full" to keep
    // the open_bins_count low, weighted by mean_residual.
    score += (mean_residual - post_res) * 0.1;

    // Final constraint: if this is the only bin that fits, prioritize it
    // by reducing the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic
    // Penalize large gaps (post_residual) that are too small to fit future items.
    // Reward bins that leave a residual which is a multiple of common item sizes (harmonic balancing).

    let mut score = post_residual as f64;

