    let remainder = post_residual % 25;
    score += (remainder as f64) * 0.5;

    // 5. Fitting bin scarcity:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Global density balance:
    // If current residual is much higher than the global mean, we are wasting space.
    if (post_residual as f64) > mean_residual {
