    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_diff;

    // Critical constraint: If this is the last chance to fit the item in an existing bin,
    // strongly incentivize picking it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Encourage filling bins tightly (minimize post_residual).
    // This is the baseline.

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.85;

        // Reward creating "perfect" pairings (e.g., residual 0 after next item)
        if post_residual == next_item_size {
