    // 3. Penalty for "Dead Space" creation:
    // If post_residual is small but > 0, it often prevents future items from fitting.
    // Penalize residuals that are too small to fit any likely item (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Distribution management:
    // If this is the last bin that can fit the item, we are forced to use it.
    // However, if we have many bins, try to consolidate.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // High priority to use the "last chance" bin to keep others open/empty.
    }

    // 5. New Bin thresholding:
    // Only open a new bin if the current bin_residual is "too good" to waste on this item,
    // or if the current item is very large and leaves an awkward, unusable gap.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin:
        // We only open it if the current score of existing bins is significantly worse.
        score += 45.0;

        // If the item is large (e.g., > 70), it's often better to start a new bin
        // than to clutter a bin that could have held two medium items.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 6. Global density balance:
    // Use mean_residual to prefer bins that are already closer to the average fill level.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
