    } else {
        0.0
    };

    // Factor in the next item: if post_residual < next_item_size, we create a dead space.
    // We penalize this heavily, weighted by how far we are into the stream.
    let next_fit_penalty = if next_item_size > 0 && post < next_item_size as f64 {
