    let balance_penalty = (post - mean_residual).powi(2) * 0.1;

    // Final score: lower is better.
    // We prioritize small post_residual (tightest fit) but add penalties for bad future outlook.
    post + sliver_penalty + next_fit_penalty + new_bin_base + balance_penalty
}

