    // 1. Penalize creating "fragmented" space that is too small for common items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (post_residual as f64 * 2.0);
    }

    // 2. Lookahead logic: if next item exists, favor bins that can accommodate both
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for potential dual-fit
        } else if post_residual < 10 {
            score += 15.0; // Penalty if current placement kills the chance for next_item
        }
    }

    // 3. Dynamic weight based on stream progression
    // Early in the stream, be more conservative with opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one fits
            score += 60.0 + (progress * 40.0);
        } else {
            // Necessary evil, normalize based on global state
            score -= (mean_residual * 0.2);
        }
    } else {
        // 4. Best-Fit variation: penalize bins that deviate significantly from the mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;

        // 5. If this is the last fitting bin, prioritize it to avoid opening a new one later
        if fitting_bins_count == 1 {
