            // Penalize creating a "stranded" bin that cannot fit the next known item.
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that can accommodate the next item.
            score -= (bin_capacity - post_residual) as f64 * 0.1;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the residual is very poor.
    // The new bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (fragmentation is high)
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // 5. Harmonic packing: Penalize remainders that are unusable (e.g., < 10)
    // assuming item sizes are generally >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10, the minimum item size).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
