pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: Favor smaller post_residual (Best Fit)
    // We apply a non-linear penalty to very small residuals (slivers) to avoid fragmentation.
    let sliver_penalty = if post > 0.0 && post < 10.0 { 25.0 / (post + 1.0) } else { 0.0 };

    // Lookahead logic: If the next item fits into the current post_residual, highly reward this bin.
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -40.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin logic: Penalize opening a new bin heavily, but scale it so that as the stream
    // progresses, the penalty for opening new bins decreases slightly to allow for better packing.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
