    // Global state coupling: If we are running out of space (many bins open), 
    // prioritize consolidating items into existing bins over creating new ones.
    let efficiency_pressure = (open_bins_count as f64 - (100.0 / (mean_residual + 1.0))) * 5.0;

    let score = post + sliver_penalty + lookahead_reward + new_bin_penalty + efficiency_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
