    }

    // 4. Balance current bin against the global mean to prevent bin fragmentation
    // If this bin's post_residual is significantly higher than the average, we penalize it
    // to force consolidation into tighter bins.
    let residual_diff = post_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.5;
    }

    // 5. Progression scaling: as we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}
